import type { Block, Citation, CoursePack } from '../../packages/course-pack/src';

type Section = { id: string; title: string; pages: [number, number]; sourceSection?: string; text: string };
type Sketch = {
  after: string; title: string; pages: [number, number]; caption: string; alternative: string;
  nodes: [label: string, detail: string][];
  edges: [from: number, to: number, label: string][];
};
type NotesTable = { after: string; title: string; pages: [number, number]; sourceSection: string; columns: string[]; rows: string[][] };
type LessonNotes = { summary: string; sections: Section[]; sketches: Sketch[]; tables?: NotesTable[]; synthesis: string };

export const notes: Record<number, LessonNotes> = {
  1: {
    summary: 'Knowledge-based AI studies how represented knowledge supports reasoning, learning, and memory in agents with limited resources.',
    sections: [
      { id: 'challenge', title: 'Why knowledge matters under limits', sourceSection: 'Conundrums in AI; Characteristics of AI Problems; Characteristics of AI Agents', pages: [5, 6], text: 'The course begins with a tension: intelligent agents have limited computation, sensors, attention, and knowledge, but face large, changing, open-ended problems. Information arrives incrementally and similar situations recur. An agent cannot simply enumerate everything or wait until it knows the whole world before acting.\n\nThe five conundrums make that tension concrete: limited resources versus difficult computation; local operations versus global constraints; deductive computation versus inductive or abductive tasks; existing knowledge versus new situations; and solving a problem versus also explaining the solution. Knowledge-based AI investigates how useful abstractions, remembered experience, and reasoning methods can address these limits. Bounded rationality means reasoning under such bounds, not possession of a universally optimal answer.' },
      { id: 'deliberation', title: 'Reasoning, learning, and memory work together', sourceSection: 'Exercise AI in Practice Watson; What is Knowledge-Based AI', pages: [6, 7], text: 'Watson answering a Jeopardy clue makes the components visible: it must interpret the clue, access relevant knowledge, choose an answer, and express it appropriately. The lesson groups interpretation and decision making under reasoning. Learning changes what the agent knows; memory stores that knowledge and makes it available when needed.\n\nThese are mutually dependent processes. Reasoning draws on memory and can produce information worth retaining. Learning needs existing knowledge and supplies future reasoning. The course calls this interacting group deliberation. Studying only an answer-producing algorithm would miss how the knowledge it uses was acquired, organized, and retrieved.' },
      { id: 'schools', title: 'Human-like and rational are different aims', sourceSection: 'Foundations The Four Schools of AI; Exercise What is KBAI; Exercise The Four Schools of AI', pages: [8, 9], text: 'The four schools cross two distinctions: thinking versus acting, and human-like versus rational or optimal performance. Thinking concerns internal reasoning; acting concerns behavior in the world. A human-like account aims to capture aspects of human cognition or behavior; a rational account asks whether inference or action meets an appropriate standard for the task.\n\nThe autonomous-car discussion shows why these distinctions matter: reaching a destination safely does not require reproducing a particular person’s driving habits. Conversely, studying human problem solving can inform an artificial agent even when the agent is evaluated on task success. The categories are perspectives, not exclusive labels for every feature of a complex system. KBAI’s cognitive-systems emphasis keeps the connection to human cognition central.' },
      { id: 'layers', title: 'Reaction, deliberation, and metacognition', sourceSection: 'What are Cognitive Systems; Cognitive System Architecture', pages: [9, 11], text: 'A cognitive system comprises interacting components rather than one isolated method. Its architecture connects percepts from the environment to actions. Reaction supplies a direct mapping, such as an immediate response to an event. Deliberation uses knowledge through reasoning, learning, and memory. Metacognition reasons about the agent’s own processes, such as noticing that a strategy is failing and changing how to reason.\n\nThese are roles, not a mandatory serial pipeline. An agent can react without first performing an explicit plan; deliberation and monitoring can also influence behavior. Changing an estimate of the external world is object-level reasoning. Evaluating or changing the method used to produce that estimate is meta-level reasoning. That distinction will return in the later lessons on mistakes and meta-reasoning.' },
    ],
    sketches: [{ after: 'deliberation', title: 'The mutually supporting processes of deliberation', pages: [7, 7], caption: 'Original relationship schematic, not a copied architecture figure. Memory supplies knowledge; learning and reasoning contribute what can be retained.', alternative: 'Memory makes stored knowledge available to reasoning. Reasoning creates learning needs and results. Learning changes knowledge retained in memory, supporting later reasoning.', nodes: [['Memory', 'Store knowledge and retrieve what is relevant.'], ['Reasoning', 'Use available knowledge to interpret and decide.'], ['Learning', 'Change knowledge in response to experience and reasoning needs.']], edges: [[0, 1, 'retrieve knowledge'], [1, 2, 'needs and results'], [2, 0, 'retain knowledge']] }],
    synthesis: 'The course’s unit of explanation is a knowledgeable cognitive agent: a representation and reasoning process situated within memory, learning, action, and monitoring. The recurring question is how these components achieve useful behavior despite limited resources.',
  },
  2: {
    summary: 'The course connects agent design with human cognition, using visual analogy to reveal representations, reasoning strategies, and the limits of performance evidence.',
    sections: [
      { id: 'purpose', title: 'What the course is trying to teach', sourceSection: 'Class Goals; Class Outcomes; Class Strategies', pages: [16, 18], text: 'The goals connect core KBAI methods, cognitive architectures, common problem-solving tasks, and cognitive science. The outcomes are more than remembering names: design, implement, evaluate, and describe an agent; apply methods to practical problems; and relate computational accounts to cognition.\n\nThe book teaches through examples, doing, reflection, collaboration, and teaching. Its worked examples make a mechanism inspectable: what is represented, what operations are available, and why an answer follows. The ebook describes historical assessments, so use the Fall 2026 syllabus for current ARC-AGI work, deadlines, and exam scopes. The learning ideas remain relevant; the old Raven project instructions are not current submission requirements.' },
      { id: 'psychometrics', title: 'Computational psychometrics and visual analogy', sourceSection: 'Introduction to Computational Psychometrics; 2x1 Matrices I; 2x1 Matrices II; 2x1 Matrices III', pages: [18, 20], text: 'Psychometrics concerns measuring human intelligence, aptitude, and knowledge. Computational psychometrics builds agents that can attempt the same kinds of tests and uses their behavior to investigate cognition. The book’s Raven’s Progressive Matrices examples ask the solver to infer relationships among visual panels and identify a fitting completion.\n\nIn a simple A-to-B, C-to-D analogy, one strategy is to infer a transformation from A to B and apply it to C. Another is to consider candidate completions and test whether their relationships fit. The examples deliberately become more ambiguous: what looks like removing one shape could also be removing another and enlarging the remaining shape. The representation and the available alternatives affect which explanation is plausible.' },
      { id: 'patterns', title: 'From pair transformations to matrix relationships', sourceSection: '2x2 Ravens Progressive Matrix I; 2x2 Ravens Progressive Matrix II; 2x2 Ravens Progressive Matrix III; 3x3 Ravens Progressive Matrix I; 3x3 Ravens Progressive Matrix II', pages: [21, 25], text: 'Larger matrices require consistency across more than one pair. The solver can examine rows, columns, and other relationships, distinguishing properties of individual objects from arrangements across panels. Some examples depend on a recurring set of features; others depend on the order of figures. A strategy that worked on an earlier pattern need not explain the next one.\n\nThe discussion contrasts inducing relationships before selecting a completion with inserting candidates and testing the resulting matrix. Equal answers do not establish equal reasoning processes. The purpose of the examples is to reveal these choices, not to treat all visual problems as one memorized transformation.' },
      { id: 'principles', title: 'Seven ideas that recur throughout KBAI', sourceSection: 'Principles of CS7637; The Cognitive Connection', pages: [25, 27], text: 'Agents represent and organize knowledge to guide reasoning. Learning is often incremental. Reasoning uses expectations from knowledge as well as incoming data: it is top-down, not only bottom-up. Agents match methods to tasks rather than using one method for everything.\n\nAgents use heuristics to seek good-enough solutions under resource limits; they exploit recurring patterns; and reasoning, learning, and memory support and constrain one another. These principles connect the later lessons. For example, case retrieval exploits recurrence, frames guide expectations, and an impasse can create a learning need.\n\nThe cognitive connection goes in both directions: hypotheses about human problem solving inform agent designs, and explicit agent mechanisms suggest hypotheses about human cognition. Comparing errors as well as successes can be informative. Success on a restricted test alone is not a complete account of intelligence or proof of a human-like internal process.' },
    ],
    sketches: [{ after: 'psychometrics', title: 'Two routes to a candidate completion', pages: [19, 20], caption: 'Original schematic of the strategy distinction in the visual-analogy discussion. The two routes can agree on an answer without using the same process.', alternative: 'Known panels can support induction of a transformation followed by transfer to the target. Alternatively, a candidate can be inserted and the completed relation tested. Both routes may accept the same candidate.', nodes: [['Known panels', 'The observed relation is evidence, not yet a unique rule.'], ['Infer then transfer', 'Describe A-to-B and apply the relation to C.'], ['Insert then test', 'Try a candidate D and check the resulting relation.']], edges: [[0, 1, 'induce relation'], [0, 2, 'test completion']] }],
    synthesis: 'A useful agent explanation connects the task, representation, reasoning choices, and evidence from evaluation. Visual analogy is a recurring vehicle for that explanation, while the seven principles provide the course’s broader organizing thread.',
  },
  3: {
    summary: 'Semantic networks make objects and relationships explicit, supporting state-space search and comparison of transformations. Their usefulness depends on the task and chosen abstraction.',
    sections: [
      { id: 'language', title: 'Representation is a language plus knowledge content', sourceSection: 'Representations; Introduction to Semantic Networks; Structure of Semantic Networks', pages: [28, 31], text: 'A knowledge representation has a language and knowledge expressed in that language. Its lexicon supplies the vocabulary, its structure says how elements can be combined, and its semantics determines what those combinations mean for inference. A semantic network uses nodes and directed, labeled links to represent objects and relationships.\n\nIn the visual example, nodes represent a circle, a diamond, and a dot; links describe relations such as inside and above. Links between representations of successive panels express transformations such as unchanged, expanded, or deleted. A dummy endpoint can record a deleted object rather than pretending it still exists. A consistent vocabulary is essential: two networks cannot be compared reliably if the same relation is encoded differently without an explicit interpretation.' },
      { id: 'good-representation', title: 'What makes a representation useful?', sourceSection: 'Characteristics of Good Representations; Discussion Good Representations', pages: [32, 33], text: 'A useful representation exposes the information and constraints needed for the task, at an appropriate level of abstraction. It should be understandable, concise without losing necessary information, and computable: the intended inferences must be possible over it.\n\nThe nutritional-label discussion illustrates the tradeoff. A label provides useful quantities, but may omit relationships among them and include information irrelevant to a particular reader. Completeness is therefore relative to the inferences a task requires, not a demand to encode every detail of the world. Omitting irrelevant visual detail can simplify an analogy, while omitting the relevant inside relation would make the desired comparison harder.' },
      { id: 'states', title: 'The same notation can represent a state space', sourceSection: 'Guards and Prisoners; Semantic Networks for Guards Prisoners; Solving the Guards and Prisoners Problem; Exercise Guards and Prisoners II', pages: [33, 36], text: 'In the guards-and-prisoners problem, each node represents a whole state: numbers on each bank and the boat’s location. An edge represents a crossing. The boat carries one or two people and cannot travel alone; a bank with guards cannot have more prisoners than guards. These conditions distinguish legal from illegal successors.\n\nExplicit state descriptions also reveal repeated states. If two sequences reach the same arrangement and boat location, their future possibilities need not be represented as unrelated situations. Identifying that repetition exposes loops that are easy to miss when solving informally. The network provides the representation; a reasoning process must still decide which states to generate, reject, or explore.' },
      { id: 'matching', title: 'Compare relationships, then resolve ambiguous matches', sourceSection: 'Represent Reason for Analogy Problems; Exercise Represent Reason for Ravens; Choosing Matches by Weights; Connections', pages: [37, 40], text: 'To compare A-to-B with C-to-a-candidate, compare the represented object relations and transformations. A candidate may preserve the spatial structure yet fail to reproduce an expansion, so a partial match is not the same as an exact match. Correspondence is also a problem: which object in one situation plays the role of which object in another?\n\nWhen more than one transformation fits, weighted matching expresses a preference. The book’s illustrative scale gives a higher weight to an easier or more similar transformation, not a larger cost. Deleting one object while leaving another unchanged can score differently from deleting one and expanding another. Those weights explain a preference under the chosen metric; they do not make the ambiguous observation uniquely determine a transformation. This distinction returns in retrieval and analogical reasoning.' },
    ],
    sketches: [{ after: 'language', title: 'A relation is more than an object property', pages: [29, 31], caption: 'Original small semantic network using the book’s spatial vocabulary. Arrow direction and relation labels specify what is inside or above what.', alternative: 'A diamond is inside a circle. A dot is above the diamond and above the circle. The nodes identify objects; directed links express these relations.', nodes: [['Dot', 'An object whose position is represented relationally.'], ['Diamond', 'The object inside the circle.'], ['Circle', 'The enclosing object.']], edges: [[0, 1, 'above'], [1, 2, 'inside'], [0, 2, 'above']] }],
    synthesis: 'Semantic networks make relationships available to computation. State-space edges encode actions; analogy links encode spatial relations and transformations. Neither the notation nor a similarity score eliminates the need for an explicit reasoning method.',
  },
  4: {
    summary: 'Generate and test separates proposing candidates from judging them. Knowledge can improve either side, while abstraction and repeated-state detection control wasted search.',
    sections: [
      { id: 'method', title: 'Generate a possibility; test whether it survives', sourceSection: 'Preview; Guards and Prisoners', pages: [43, 44], text: 'Generate and test is a general problem-solving method for situations where the agent cannot directly derive a guaranteed solution. The generator proposes possible solutions or successor states; the tester evaluates them against relevant requirements. The surviving possibilities support further search or a candidate answer.\n\nThe lesson reuses guards and prisoners. A simple generator proposes crossings, while a simple tester removes states that violate the bank-safety rule. This separates the representation from its use: a semantic network describes states and transitions, but does not itself explain which candidates an agent produces or rejects.' },
      { id: 'repetition', title: 'Legal does not mean productive', sourceSection: 'Exercise Generate and Test II; Dumb Generators, Dumb Testers; Smart Testers', pages: [45, 47], text: 'A tester that checks only legality can retain repeated states, including returns to the initial state. Repeating expansion without recognizing equivalence creates a large search tree even in a small world. This is the lesson’s combinatorial-explosion problem: many generated paths need not correspond to genuinely new states.\n\nA smarter tester checks whether a state has already been visited and can dismiss repeated states as well as illegal ones. Equivalent states can be merged in the representation. A branch with no remaining productive successor need not be mistaken for progress merely because its current state is legal. The representation must include all relevant state information, including the boat location, for that comparison to be meaningful.' },
      { id: 'knowledge', title: 'Put knowledge in the generator, tester, or both', sourceSection: 'Smart Generators; Discussion Smart Generators and Testers', pages: [47, 49], text: 'Instead of generating a repeated or illegal state and rejecting it afterward, a smarter generator can avoid proposing it. The example of sending a lone person to an empty bank illustrates an unproductive return: the only next crossing undoes the move. Knowledge of that situation can prevent generation or support rejection.\n\nThe division of responsibility is a design choice. A richer generator may save testing work; a richer tester may keep generation simple. “Smart” here means endowed with relevant knowledge or discrimination, not a different kind of intelligence. Either way, broad generation without useful knowledge can be expensive, and rejection rules must preserve possibilities needed for a solution.' },
      { id: 'abstraction', title: 'The representation determines the candidate space', sourceSection: 'Generate Test for Ravens Problems; Semantic Networks for Generate and Test; Generate Test for Ravens Problems II', pages: [49, 50], text: 'Visual transformations can vary continuously: an object can move many distances or expand by many amounts. If every pixel-level variation is a separate candidate, generation becomes unwieldy. A semantic representation can instead express the relevant relation, such as outside or expanded, without enumerating irrelevant geometric detail.\n\nThe generator can transfer a represented transformation to create a candidate completion, and the tester can compare it with the choices. This illustrates the coupling between representation and method: an abstraction makes certain distinctions available and suppresses others. The right abstraction depends on the task; ignoring a detail is helpful only when the solution does not require it.' },
    ],
    sketches: [{ after: 'repetition', title: 'A candidate can fail more than one test', pages: [44, 47], caption: 'Original schematic of generate-and-test roles. Legality, repeated-state detection, and goal testing answer different questions.', alternative: 'The current state feeds a generator of successor candidates. A tester removes illegal or already visited states. Surviving states are checked against the goal and otherwise become inputs for further generation.', nodes: [['Current state', 'The represented arrangement from which search proceeds.'], ['Generate candidates', 'Propose possible next states.'], ['Test candidates', 'Check legality and whether the state was already visited.'], ['Surviving state', 'Check the goal; if not finished, continue search.']], edges: [[0, 1, 'successors'], [1, 2, 'candidate states'], [2, 3, 'retain useful states'], [3, 0, 'continue search']] }],
    synthesis: 'Generate and test explains the control missing from a bare state-space drawing. Its effectiveness depends on what candidates are proposed, what knowledge the tests use, and whether the representation makes meaningful comparisons affordable.',
  },
  7: {
    summary: 'Frames organize stereotypical situations into slots and fillers. Defaults, inheritance, and linked frames let prior knowledge guide interpretation without making every expectation a fact.',
    sections: [
      { id: 'slots', title: 'Slots describe what to expect; fillers describe this instance', sourceSection: 'Exercise Ashok Ate a Frog; How do we make sense of a sentence; Exercise Making sense of a sentence', pages: [83, 85], text: 'A frame is a structured representation of a stereotypical object, situation, or event. Slots describe the relevant attributes or roles; fillers supply values. For the eating frame, slots include the eater, what is eaten, location, time, and possible utensils. Different eating sentences instantiate the same structure with different fillers.\n\n“Ashok ate a frog” supplies an eater and an object but not every detail a reader infers. The frame supplies expectations about eating, including possible default values for the object’s location afterward. A filler obtained from the sentence and a default inferred from prior knowledge have different evidential status. The book’s guessed mood after eating illustrates that expectations can be wrong, not that eating always makes someone happy.' },
      { id: 'structure', title: 'Link frames, inherit structure, and override defaults', sourceSection: 'Complex Frame Systems; Properties of Frames', pages: [85, 87], text: 'A filler can point to another frame rather than be a simple value. An eating-event frame can link to a person frame with food preferences and to a restaurant frame with its location. Connecting frames combines knowledge from several sentences and supports discourse-level interpretation.\n\nThe three central properties are stereotypes, defaults with exceptions, and inheritance. A subclass or instance can inherit slots and values from a more general frame and add or override information. This avoids restating everything, but exceptions must be managed. Stereotypes can also vary with culture and context. A default provides a defeasible expectation, not a logical necessity that overrides contrary evidence.' },
      { id: 'connections', title: 'Frames connect earlier representations', sourceSection: 'Frames and Semantic Nets; Frames and Production Systems', pages: [88, 89], text: 'The same object-and-relation information in a semantic network can be expressed in frames. A diamond’s frame can have an inside slot whose filler refers to a circle’s frame. The drawing of an edge and the named slot are different notations for a represented relationship.\n\nThe feature-value working memory in the production-system lesson can also be understood as frame-like structure. An input cue such as an eating verb retrieves a relevant frame from semantic memory. Its slots guide attention to expected information; the incoming sentence then supplies particular fillers. This connects representation with memory and processing rather than leaving the frame as a static form.' },
      { id: 'expectations', title: 'Understanding combines top-down expectation and bottom-up input', sourceSection: 'Exercise Frames Complex Understanding; The Cognitive Connection', pages: [89, 91], text: 'The earthquake story illustrates the process: retrieve an earthquake frame, look for relevant roles such as location and magnitude, then fill them from the story. The frame provides top-down expectations, while the actual wording provides bottom-up evidence.\n\nA frame cannot infer everything merely because a slot exists. In the story, connecting the place described in the text with a broader geographical location needs additional knowledge; the frame alone does not supply that reasoning. Frames make useful information organized and accessible, but other reasoning methods must interpret relationships, resolve missing information, and handle exceptions.' },
    ],
    sketches: [{ after: 'slots', title: 'An eating frame separates input from expectation', pages: [83, 85], caption: 'Original schematic of slots and fillers. The same frame can be instantiated by different sentences; defaults remain revisable.', alternative: 'An eating event expects eater, object, location, and time slots. The sentence supplies Ashok as eater and frog as object. Location and time remain unspecified; any default about the aftermath comes from prior knowledge, not the sentence.', nodes: [['Eating frame', 'Slots describe expected participants and circumstances.'], ['Eater: Ashok; object: frog', 'Fillers explicitly supplied by this sentence.'], ['Location and time unknown', 'The sentence does not specify these fillers.']], edges: [[0, 1, 'input fills slots'], [0, 2, 'unfilled slots']] }],
    synthesis: 'Frames explain how structured prior knowledge helps make sense of incomplete input. Their strength is organized expectation; their limitation is that defaults, inherited values, and open slots do not by themselves establish every missing fact.',
  },
  8: {
    summary: 'Learning by recording cases stores experiences for direct reuse. Nearest-neighbor retrieval makes similarity explicit, but a close case is not necessarily a solution that can be reused unchanged.',
    sections: [
      { id: 'cases', title: 'A case encapsulates an experience', sourceSection: 'Exercise Block World I; Learning by Recording Cases', pages: [94, 95], text: 'A case records a past situation together with its solution or outcome. Learning by recording cases retains those experiences instead of immediately abstracting a general rule. A new problem acts as a probe into memory; retrieve a similar case and reuse its solution.\n\nThe colored-block example predicts a new block’s color from a remembered block of similar shape and size. Familiar routines such as tying shoelaces illustrate how memory can reduce the need to reason from scratch. This is direct reuse: it is distinct from adapting a solution to a different problem, which the next lesson adds.' },
      { id: 'nearest', title: 'Operationalize “most similar” with a distance', sourceSection: 'Case Retrieval by Nearest Neighbor; Exercise Retrieval by Nearest Neighbor', pages: [95, 97], text: 'Represent the stored blocks and the new block by width and height in the same feature space. Euclidean distance is the square root of the sum of squared coordinate differences. The nearest neighbor is the recorded case with the smallest distance to the new problem under that representation.\n\nThe calculation makes the comparison reproducible, but the representation determines what similarity means. Width and height support the lesson’s example; they do not show that any similarly shaped object must have the same color. Retrieval chooses a case under the selected metric, not a guarantee that its answer is correct.' },
      { id: 'dimensions', title: 'A route has both an origin and a destination', sourceSection: 'Exercise Recording Cases in Real Life; Nearest Neighbor for Complex Problems; Nearest Neighbor in k-Dimensional Space', pages: [97, 98], text: 'The route example makes one-feature similarity inadequate. A stored route can start close to the new origin but finish far from the requested destination; another can finish close but start far away. Comparing only either endpoint selects a misleading case.\n\nThe lesson represents both endpoints by coordinates, making a four-dimensional comparison. More generally, compare a case and problem in k-dimensional space by summing squared differences across the relevant coordinates. The ebook calls this KNN while discussing k dimensions; it does not teach a majority vote over k retrieved neighbors here. Keep the dimensionality of the representation separate from the number of neighbors selected.' },
      { id: 'limits', title: 'Retrieval is useful even when direct reuse fails', sourceSection: 'Nearest Neighbor in k-Dimensional Space; Wrap Up; The Cognitive Connection', pages: [98, 100], text: 'High-dimensional descriptions can make similarity harder to compute or interpret. Some cases also require qualitative features rather than numerical coordinates. Most importantly, a nearby route need not start and end at exactly the new problem’s locations, so copying it unchanged may fail.\n\nThis motivates case-based reasoning: alternative retrieval organizations, adaptation, and evaluation. The cognitive connection emphasizes recurring problems and the contribution of memory to intelligence. Recording cases does not remove reasoning; it shifts the balance toward remembered experience where that experience is relevant.' },
    ],
    sketches: [{ after: 'dimensions', title: 'Compare both endpoints before reusing a route', pages: [97, 98], caption: 'Original schematic of the lesson’s route-similarity distinction. Endpoint similarity chooses a candidate case; it does not repair the endpoint differences.', alternative: 'A new origin and destination form one problem description. Compare both with stored routes. A route close at both endpoints is retrieved; origin-only or destination-only closeness can select a different route.', nodes: [['New origin + destination', 'Four coordinates describe both endpoints.'], ['Compare stored routes', 'Measure differences using both endpoints.'], ['Retrieve closest case', 'The candidate can still need adaptation.']], edges: [[0, 1, 'problem features'], [1, 2, 'nearest under metric']] }],
    synthesis: 'Remembered experience can supply a candidate answer quickly. Feature representation and distance define retrieval; whether the answer transfers unchanged is a separate question.',
  },
  9: {
    summary: 'Case-based reasoning extends case retrieval with adaptation, evaluation, and selective storage. Memory organization and feedback determine whether experience can solve a new problem.',
    sections: [
      { id: 'cycle', title: 'Retrieve, adapt, evaluate, store', sourceSection: 'Recording Cases to Case-Based Reasoning; Assumptions of Case-Based Reasoning', pages: [102, 104], text: 'A similar case may be useful without being a complete solution. The route retrieved in the previous lesson has different endpoints from the new request. Case-based reasoning retrieves that experience, adapts its solution, evaluates the resulting candidate, and stores useful new experience.\n\nThe method assumes recurring problem patterns and that similar problems often have similar solutions. Neither is universal: fastening a shoe with laces and fastening one with Velcro are similar goals with different mechanisms. Retrieval proposes a starting point, not evidence that adaptation will be small or successful.' },
      { id: 'adapt', title: 'Three ways to adapt an old solution', sourceSection: 'Case Adaptation; Case Adaptation by Model of the World; Case Adaptation by Recursive Reasoning; Case Adaptation by Rules', pages: [104, 108], text: 'Model-based adaptation uses knowledge of how the world works. In the route example, a map supplies a connection from the old route’s endpoint to the new destination. The case contributes much of the path; the model supplies the missing change.\n\nRecursive case-based adaptation turns an unsolved part into another retrieval problem. Combine a home-to-office case with an office-to-restaurant case to solve home-to-restaurant. The subsolutions must fit together; retrieving two cases is not enough without a valid composition.\n\nRule-based adaptation applies a heuristic such as reversing a route to return home. A rule of thumb may work often but fail on one-way streets. This is why adaptation creates a candidate for evaluation rather than automatically a correct answer. The three methods use different knowledge sources: a world model, other cases, or adaptation rules.' },
      { id: 'evaluate', title: 'Evaluate before treating a candidate as success', sourceSection: 'Case Evaluation; Case Storage; Case Storage by Index', pages: [108, 110], text: 'Evaluation asks whether the adapted solution meets the new problem’s requirements. Simulation, execution, prototyping, or critique can provide evidence, depending on the domain and cost of failure. The reversed route may fail because a turn is prohibited, even though its derivation looked plausible.\n\nA new problem and evaluated solution can become a case. Storage must also make later retrieval possible. An index records features useful for finding the case, such as route origin, destination, speed, or scenic quality. The features useful for retrieval depend on the future task, so indexing is part of the reasoning design, not just archiving a transcript.' },
      { id: 'organization', title: 'Discrimination trees organize cases by questions', sourceSection: 'Case Storage by Discrimination Tree; Exercise Storage by Discrimin Tree I; Exercise Storage by Discrimin Tree II; Case Retrieval Revisited', pages: [111, 114], text: 'A discrimination tree places cases at leaves and feature questions at internal nodes. Answers select branches. To store a new case, follow its answers; if it reaches a leaf shared with an existing case, add a question that separates them. To retrieve, use the new problem’s features to follow the same organization.\n\nThe navigation example asks questions about origin coordinates. A question can prune a whole branch instead of comparing every case in a table. The tree need not be binary, and its usefulness depends on discriminating questions and the selected indices. This retrieval organization is distinct from adapting whatever case it returns.' },
      { id: 'feedback', title: 'The process can loop, and storage has a utility cost', sourceSection: 'Advanced Case-Based Reasoning; Wrap Up', pages: [115, 117], text: 'Evaluation failure can return to adaptation or to retrieval of a different case. An exact match can skip adaptation but still needs evaluation. A failed case can be worth storing because it warns of a future failure; a redundant successful case may add little value.\n\nThe utility problem is that accumulating cases can make retrieval less efficient. Selective storage seeks experience that expands useful coverage, not simply a larger library. The cycle therefore connects learning, memory, and reasoning: learn experience, organize and retrieve it, then reason about adapting and testing it.' },
    ],
    sketches: [{ after: 'feedback', title: 'Case-based reasoning includes feedback', pages: [102, 103], caption: 'Original schematic of the four roles, with evaluation feedback explained in the text. Retrieval and adaptation are not interchangeable.', alternative: 'Retrieve a relevant case, adapt it to the new problem, evaluate the candidate, and store useful evaluated experience. A failed evaluation can require another adaptation or a different retrieved case.', nodes: [['Retrieve', 'Find a relevant prior problem and solution.'], ['Adapt', 'Change the solution for current requirements.'], ['Evaluate', 'Test whether the candidate meets those requirements.'], ['Store', 'Retain useful experience with retrieval indices.']], edges: [[0, 1, 'prior solution'], [1, 2, 'candidate'], [2, 3, 'evaluated experience'], [2, 0, 'failure: reconsider']] }],
    synthesis: 'Case-based reasoning does not mean copying the nearest remembered answer. It requires knowledge for adaptation, evidence from evaluation, and an organization that makes valuable experience retrievable.',
  },
  10: {
    summary: 'Incremental concept learning revises a concept from labeled examples. Generalization includes missed positives; specialization excludes mistaken negatives; heuristics and background knowledge guide the change.',
    sections: [
      { id: 'revision', title: 'Learn a concept, not just another case', sourceSection: 'Exercise Identifying a Foo I; Exercise Identifying a Foo II; Exercise Identifying a Foo III; Incremental Concept Learning', pages: [120, 123], text: 'The agent receives examples one at a time, labeled positive or negative. Unlike recording raw cases for later reuse, it abstracts a concept description. That description must cover positive examples and exclude negative ones.\n\nFor each new example, compare its label with whether the current concept covers it. A covered positive or excluded negative requires no change. A missed positive calls for generalization; a covered negative calls for specialization. The learner must still respect earlier examples. Learning from a small sequence is underdetermined: many possible changes can fit the evidence, so the representation, example order, and background knowledge matter.' },
      { id: 'links', title: 'The arch example revises relationships', sourceSection: 'Variabilization; Generalization to Ignore Features; Specialization to Require Features; Specialization to Exclude Features', pages: [123, 126], text: 'The first arch example is variabilized: replace particular brick names with variables or categories while retaining their relationships. A later positive example lacks an incidental relationship in the initial description, so drop-link removes that constraint to include both examples.\n\nA negative example lacking the required support relation motivates require-link: mark that relation as necessary. Another negative example has the supporting blocks touching, motivating forbid-link: exclude that relationship. These are different changes. Dropping a link loosens a description, requiring one tightens it, and forbidding one explicitly rules out its presence. A near miss is informative because it differs from a positive structure in a revealing way.' },
      { id: 'knowledge', title: 'Generalization can change categories or value ranges', sourceSection: 'Generalization to Abstract Features; Generalization with Background Knowledge; Heuristics for Concept Learning', pages: [127, 130], text: 'A positive arch with a wedge where the description allowed only a brick can be included by enlarge-set: allow brick or wedge. If background knowledge says both are kinds of block, climb-tree generalizes to their shared category. These are not the same inference: the shared category comes from additional knowledge.\n\nClose-interval extends an allowed continuous range to cover observed values, such as including a larger dog after seeing only small ones. The heuristics constrain a large space of possible revisions; they do not prove that an arbitrary generalization is the intended concept. Preserve the distinction between what the examples show and what background knowledge licenses.' },
      { id: 'limits', title: 'The learned definition is limited by the evidence', sourceSection: 'An Alternative Visualization; Final Concept of a Foo; The Cognitive Connection', pages: [129, 134], text: 'The repeated foo examples make the learner’s decisions inspectable: variabilize, compare structures, revise for labeled differences, and use a supplied category hierarchy where available. The final definition need not contain required links that the input sequence never justified, nor generalizations that the background knowledge never supplied.\n\nOvergeneralization includes things that should be excluded; overspecialization excludes things that should be included. Labels and carefully contrasting examples help repair both, but the resulting concept remains relative to the represented features and available evidence. An example that the representation cannot distinguish cannot teach the missing distinction by itself.' },
    ],
    sketches: [{ after: 'revision', title: 'The label determines the direction of repair', pages: [122, 123], caption: 'Original decision schematic. Correctly covered positives and correctly excluded negatives leave the current concept unchanged.', alternative: 'Compare the current concept with a labeled example. If a positive is missed, generalize. If a negative is covered, specialize. Otherwise retain the current definition.', nodes: [['Labeled example + concept', 'Check the label and whether the definition covers the example.'], ['Missed positive', 'Generalize to include it while respecting earlier examples.'], ['Covered negative', 'Specialize to exclude it while retaining positives.']], edges: [[0, 1, 'positive not covered'], [0, 2, 'negative covered']] }],
    synthesis: 'Incremental learning changes a knowledge structure in response to informative examples. The core operation is controlled revision, with relationships and background categories determining what can be generalized or specialized.',
  },
  11: {
    summary: 'Classification organizes percepts into useful concepts for action. Concept hierarchies guide search, while axiomatic, prototype, and exemplar concepts require different kinds of representation and inference.',
    sections: [
      { id: 'equivalence', title: 'Classification compresses the action-selection problem', sourceSection: 'Classifying Birds; The Challenge of Classification; Equivalence Classes', pages: [137, 140], text: 'Classification maps sets of percepts into concepts or equivalence classes. Instead of choosing an action separately for every possible combination of observed features, an agent groups situations that can be treated alike for the task. This can make action selection manageable.\n\nThe bird examples show why selecting features matters: the ability to fly does not characterize every bird, since penguins and ostriches provide counterexamples. An equivalence class is useful relative to what the agent needs to do. It does not mean every member is identical in every property. Learning a concept and using it to classify are related but distinct tasks.' },
      { id: 'hierarchy', title: 'Establish and refine through a concept hierarchy', sourceSection: 'Concept Hierarchies; Exercise Concept Hierarchies', pages: [141, 143], text: 'Organize concepts into superclasses and subclasses. A top-down establish-and-refine process first determines a broad category, then considers its finer distinctions. The animal example proceeds toward vertebrate, bird, and a particular kind of bird.\n\nThe organization guides attention: size may not distinguish bird from mammal, but can matter when separating examples within birds. Shared subclass properties can inform a superclass where the concept supports such a definition. The book cautions that this works for some formal concepts, not every everyday concept. Organization controls the reasoning sequence rather than merely arranging labels for display.' },
      { id: 'types', title: 'Three kinds of concept do not have the same definition', sourceSection: 'Types of Concepts; Axiomatic Concepts; Prototype Concepts; Exemplar Concepts', pages: [143, 145], text: 'An axiomatic concept has explicit necessary and sufficient conditions, as with the geometrical definition of a circle. Classification can test those conditions. A prototype concept instead has typical properties that may admit exceptions. The chair example uses a frame with defaults; a stool can override the expected back without ceasing to fit the broader category in the example.\n\nAn exemplar concept is conveyed through examples without an agreed necessary-and-sufficient or typical-property definition, illustrated by beauty. Such concepts can depend on culture or individuals. A frame is a representation form; a prototype is a kind of concept content. Confusing these levels would make every frame appear to be a prototype classifier and every everyday concept appear formally definable.' },
      { id: 'bottom-up', title: 'Choose the direction of inference to fit the task', sourceSection: 'Order of Concepts; Exercise Order of Concepts; Bottom-Up Search', pages: [145, 147], text: 'Top-down establish-and-refine fits classification within an existing hierarchy. Bottom-up identify-and-abstract starts with observed lower-level features and derives higher-level summaries. The economic-indicator example combines known indicators into broader quantities and then a prediction.\n\nThe lesson’s point is method-task fit, not that this illustration guarantees stock-market prediction. Different concept types and organizations afford different methods: formal conditions, prototypes with exceptions, or remembered exemplars. Classification is therefore a family of reasoning tasks rather than one universal feature checklist.' },
    ],
    sketches: [{ after: 'hierarchy', title: 'A hierarchy guides successive distinctions', pages: [141, 142], caption: 'Original small hierarchy schematic using the source’s categories. The links are subclass relations, not actions or a biological claim about every feature.', alternative: 'Bird is a subclass of vertebrate. Eagle and penguin are subclasses of bird. Establish the broader category before refining toward one of the more specific categories.', nodes: [['Vertebrate', 'A broad category in the example hierarchy.'], ['Bird', 'A more specific category to establish.'], ['Eagle', 'One refinement within birds.'], ['Penguin', 'Another refinement, with different distinguishing properties.']], edges: [[0, 1, 'refine category'], [1, 2, 'refine category'], [1, 3, 'refine category']] }],
    synthesis: 'Classification bridges perception and action through organized concepts. What counts as membership, and how to infer it, depends on the kind of concept and the structure of the task.',
  },
  12: {
    summary: 'Logic separates formal knowledge from inference. Connectives, truth-preserving rewrites, quantifiers, and resolution show precisely why a conclusion follows from stated premises.',
    sections: [
      { id: 'formal', title: 'A knowledge base and an inference engine have different jobs', sourceSection: 'Why do we need formal logic; Predicates; Conjunctions and Disjunctions; Implies', pages: [149, 153], text: 'A logical agent has a knowledge base of statements and an inference engine that applies rules to derive conclusions. Formal notation makes the assertions and steps precise. A predicate expresses a property or relation; connectives form compound statements using not, and, or, and implication.\n\nConjunction requires both components, disjunction allows either or both, and negation reverses a truth value. An implication states that when its antecedent holds its consequent must hold. Soundness means deriving only conclusions supported by the premises; completeness means the inference system can derive every entailed conclusion within the relevant logic. Neither property makes incorrect premises into true statements about the world, nor guarantees an inexpensive search.' },
      { id: 'truth', title: 'Truth tables justify rewrites', sourceSection: 'Truth Tables; Exercise Commutative Property; Exercise Distributive Property; Exercise Associative Property; Exercise de Morgans Law; Truth of Implications; Implication Elimination', pages: [154, 159], text: 'A truth table enumerates assignments to simple statements and evaluates a compound statement. Two expressions are equivalent when their truth values agree on every assignment. This justifies changing an expression’s form without changing what it asserts.\n\nAnd and or are commutative and associative. Distribution moves between conjunctions and disjunctions in equivalent forms. De Morgan’s laws turn not(A and B) into not A or not B, and not(A or B) into not A and not B. Implication elimination rewrites A implies B as not A or B. The implication is false only when A is true and B is false; a false antecedent does not establish B as a fact. These rewrites prepare statements for systematic inference.' },
      { id: 'inference', title: 'Valid inference is not guessing the converse', sourceSection: 'Rules of Inference; Prove Harry is a bird', pages: [159, 160], text: 'Modus ponens uses A implies B together with A to infer B. Modus tollens uses A implies B together with not B to infer not A. The bird example instantiates an asserted rule about feathers and an observed fact about Harry to derive the asserted classification.\n\nKnowing B does not in general license A, and knowing not A does not license not B. The consequent might hold for another reason. A proof explains what follows from a particular knowledge base; it does not replace checking whether that knowledge base correctly models the domain.' },
      { id: 'quantifiers', title: 'Variables and quantifiers express scope', sourceSection: 'Universal Quantifiers', pages: [161, 161], text: 'Propositional statements concern fixed assertions. First-order logic introduces variables within predicates and quantifiers that specify their scope. A universal quantifier says a statement holds for every value in the specified domain; an existential quantifier says it holds for at least one.\n\nA general animal rule can be written once with a universally quantified variable instead of separately for every named animal. An existential claim must not be silently strengthened into a universal one. The lesson introduces this language, then returns to propositional examples for resolution. It does not provide a full treatment of first-order unification or Skolemization.' },
      { id: 'resolution', title: 'Resolution proves by refuting the negated conclusion', sourceSection: 'A Simple Proof; A More Complex Proof; Exercise Proof I; Exercise Proof II; Exercise Proof III; Exercise Proof IV; Exercise Proof V; Exercise Proof VI', pages: [162, 169], text: 'Convert the knowledge base to conjunctive normal form (CNF): a conjunction of clauses, each a disjunction of literals. A literal is an atom or its negation; a single literal is also a clause. Eliminate implications, move negations inward using De Morgan’s laws, and distribute where required. Add the negation of the conclusion you want to establish.\n\nResolution combines two clauses containing complementary literals. Resolving A or B with not A or C yields B or C: if both original clauses hold, the remaining alternatives must hold. The empty clause has no surviving alternative and represents contradiction. If the knowledge base plus the negated goal yields that contradiction, the goal is entailed by the knowledge base.\n\nThe assembly-line robot first uses “not can-move implies not liftable” and observes “not can-move.” In CNF the rule is “can-move or not liftable.” To prove not liftable, temporarily add liftable. Resolve it against not liftable in the rule to derive can-move; resolve that against the observed not can-move to obtain the empty clause. In the longer example, the rule also requires battery-full: its CNF clause is “can-move or not battery-full or not liftable.” Resolving with liftable, battery-full, and not can-move again produces contradiction.\n\nThe bird proof demonstrates the same process with wings and fur. Proof search still requires choosing clauses and may be costly; one unfinished branch without a contradiction is not proof that the goal is false. Entailment is relative to the premises, and inconsistent premises themselves undermine a useful account of the world.' },
    ],
    sketches: [{ after: 'resolution', title: 'The robot’s refutation, clause by clause', pages: [163, 163], caption: 'Original proof schematic of the book’s simple robot example. Liftable is a temporary negated-goal assumption, not an observed fact.', alternative: 'Use the rule clause can-move OR NOT liftable. Add liftable, the negation of the desired conclusion NOT liftable. Resolve the two clauses to obtain can-move. Resolve can-move with the observed NOT can-move to obtain the empty clause, proving NOT liftable from these premises.', nodes: [['can-move OR NOT liftable', 'CNF form of the asserted rule.'], ['can-move', 'Resolve the rule with the temporary assumption liftable.'], ['Empty clause', 'Resolve can-move with the observed NOT can-move.']], edges: [[0, 1, 'resolve with liftable'], [1, 2, 'with NOT can-move']] }],
    tables: [
      { after: 'truth', title: 'Implication truth table', sourceSection: 'Truth of Implications; Implication Elimination', pages: [158, 159], columns: ['A', 'B', 'A implies B', 'not A or B'], rows: [['true', 'true', 'true', 'true'], ['true', 'false', 'false', 'false'], ['false', 'true', 'true', 'true'], ['false', 'false', 'true', 'true']] },
      { after: 'inference', title: 'Valid inference forms', sourceSection: 'Rules of Inference', pages: [159, 159], columns: ['Form', 'Premises', 'Conclusion'], rows: [
        ['Modus ponens', 'A implies B; A', 'B'],
        ['Modus tollens', 'A implies B; not B', 'not A'],
      ] },
      { after: 'resolution', title: 'The robot’s CNF clauses', sourceSection: 'A Simple Proof; A More Complex Proof', pages: [162, 165], columns: ['Form', 'Premises or rewrite', 'What follows'], rows: [
        ['Simple robot rule', 'not can-move implies not liftable', 'CNF: can-move OR NOT liftable'],
        ['Robot observation', 'NOT can-move', 'A unit clause from the observed state'],
        ['Negate the goal', 'Goal: NOT liftable; temporarily add liftable', 'Resolve with the rule to derive can-move, then with the observation to derive the empty clause'],
        ['Longer robot rule', '(NOT can-move AND battery-full) implies NOT liftable', 'CNF: can-move OR NOT battery-full OR NOT liftable'],
      ] },
    ],
    synthesis: 'Logic supplies a precise language for knowledge and a checkable account of inference. Resolution brings notation, equivalent rewrites, and proof by contradiction together; planning will use this precision to describe states, actions, and goals.',
  },
  13: {
    summary: 'Planning represents states, goals, and action conditions explicitly, then coordinates subplans so achieving one goal does not prevent another.',
    sections: [
      { id: 'operators', title: 'States, goals, and operators make action reasoning precise', sourceSection: 'Painting a Ceiling; States; Operators; Exercise Operators; Planning and State Spaces', pages: [173, 177], text: 'A state specifies assertions about the world; a goal specifies assertions to achieve. An operator has preconditions that must hold before it applies and postconditions describing its effects. Assertions not changed by an operator can persist to the next state. This makes a plan a checkable sequence, not merely an informal intention.\n\nThe robot must paint both a ceiling and a ladder. Climbing requires the robot on the floor and a dry ladder; painting the ceiling requires the robot on the ladder. Painting the ladder leaves it wet. The printed operators distinguish painted from dry: achieving the painted-ladder goal can remove the dry-ladder condition needed for climbing. Positive preconditions are a convention of the illustrated planning notation, not a universal law that planning can never use negative conditions.' },
      { id: 'partial-order', title: 'Detect goal clobbering and impose the needed order', sourceSection: 'Planning; Partial Order Planning; Partial Planning; Detecting Conflicts; Open Preconditions', pages: [177, 182], text: 'A linear treatment can choose to paint the ladder first because that immediately achieves one goal, then discover that the wet ladder prevents climbing to paint the ceiling. The plan for one goal clobbers a condition required by another.\n\nThe lesson constructs subplans, compares their effects and required conditions, and resolves conflicts by promoting or demoting their order. Paint the ceiling before painting the ladder. An open precondition is a required condition not yet supported in the combined plan: after painting the ceiling, the robot must descend to establish being on the floor before painting the ladder. Adding that action joins the subplans. Partial-order planning imposes necessary dependencies rather than assuming all goals can be achieved independently in any order.' },
      { id: 'blocks', title: 'The blocks-world conflict is now explicit', sourceSection: 'Exercise Partial Order Planning I; Exercise Partial Order Planning II; Exercise Partial Order Planning III; Exercise Partial Order Planning IV; Exercise Partial Order Planning V', pages: [182, 185], text: 'Moving x onto y requires both blocks clear in the illustrated world. Putting A on B makes B no longer clear, so it interferes with moving B onto C. Putting B on C similarly interferes with moving C onto D. Comparing those effects with the next action’s preconditions exposes the ordering problem left open by means-ends analysis and problem reduction.\n\nThe goal-supporting tower must therefore be built from the bottom upward after necessary clearing moves. This is not because “bottom upward” is an unexplained preference: it follows from the represented clear conditions and the effects of stacking. The source’s planning mechanism turns that tacit reasoning into explicit dependencies.' },
      { id: 'hierarchy', title: 'Hierarchical plans use knowledge at several levels', sourceSection: 'Hierarchical Task Network Planning; Hierarchical Decomposition; Hierarchical Planning', pages: [185, 186], text: 'A long sequence of low-level block moves can be grouped into macro operators such as unstack and stack-ascending. A macro has conditions and a decomposition into lower-level actions. Planning at the higher level reduces the apparent search space; expanding the macro supplies the detailed operations.\n\nA hierarchical task network represents those task decompositions. The power comes from additional knowledge about useful abstractions and how to realize them, not merely renaming a long action list. Hierarchical planning and partial ordering address different concerns: abstraction organizes levels of a plan, while ordering resolves dependencies and conflicts among actions.' },
    ],
    sketches: [{ after: 'partial-order', title: 'The painting plan preserves the conditions it needs', pages: [179, 182], caption: 'Original dependency schematic. Painting the ladder too early removes the dry-ladder condition required by the climbing subplan.', alternative: 'Climb the dry ladder, paint the ceiling, descend to the floor, then paint the ladder. Descending establishes the floor condition needed for painting the ladder; painting it last avoids blocking climbing.', nodes: [['Climb ladder', 'Requires robot on floor and ladder dry.'], ['Paint ceiling', 'Requires robot on ladder; establishes painted ceiling.'], ['Descend ladder', 'Establishes robot on floor.'], ['Paint ladder', 'Requires robot on floor; leaves ladder painted and wet.']], edges: [[0, 1, 'robot on ladder'], [1, 2, 'ceiling completed'], [2, 3, 'robot on floor']] }],
    synthesis: 'Planning adds explicit action conditions and inter-goal dependencies to goal-directed search. Partial ordering protects necessary conditions; hierarchical decomposition exploits knowledge about useful subplans.',
  },
  14: {
    summary: 'Understanding uses thematic-role frames, grammatical cues, and background categories to interpret events and disambiguate meanings.',
    sections: [
      { id: 'roles', title: 'Meaning is organized around an event and its roles', sourceSection: 'The Earthquake Report; Thematic Role Systems', pages: [190, 192], text: 'A thematic-role system is a frame system for an action or event. It organizes participants by semantic roles such as agent, object, beneficiary, instrument, source, destination, and conveyance. These are different from lexical categories such as noun and verb or syntactic categories such as noun phrase.\n\nIn the pancake example, the maker is the agent, pancakes the object, the person they are made for the beneficiary, and the griddle the instrument. The representation supports questions about who did what for whom. The lesson treats meaningful inferences as evidence of understanding, while reminding us that expectations inferred from an event are not necessarily explicit statements in the sentence.' },
      { id: 'constraints', title: 'Prepositions constrain a role without uniquely deciding it', sourceSection: 'Constraints; Resolving Ambiguity in Prepositions', pages: [192, 193], text: 'The preposition by can indicate an agent, a conveyance, or a location. Its presence narrows possible roles, but does not choose one alone. Background knowledge about people, trains, and places helps distinguish “written by a person,” “travel by train,” and “standing by a statue.”\n\nAn ontology supplies categories for that background knowledge. Lexical and structural cues act as probes into memory; retrieved role knowledge then generates top-down expectations. Understanding combines that knowledge with the actual words rather than proceeding only from syntax or only from an unconstrained prior guess.' },
      { id: 'ambiguity', title: 'Select a verb sense whose frame fits the context', sourceSection: 'Ambiguity in Verbs; Resolving Ambiguity in Verbs; Exercise Resolving Ambiguity in Verbs', pages: [194, 197], text: 'A word such as take has several meanings, with different thematic-role frames. “Took my blood pressure” calls for a measurement interpretation, while taking an object from someone supplies an object and source. Background categories rule out inappropriate interpretations; prepositions and particles such as from or over impose further constraints.\n\nThe agent activates candidate senses and tests whether their expected roles fit the sentence. A frame that cannot accommodate the known categories or required roles is discarded. The killing examples similarly distinguish people dying in an earthquake from proposals being rejected. A pun can deliberately satisfy more than one interpretation, so ambiguity is not always an error with one answer to recover.' },
    ],
    sketches: [{ after: 'constraints', title: 'A grammatical cue and world knowledge cooperate', pages: [192, 193], caption: 'Original schematic of resolving a thematic role. The preposition narrows the alternatives; the ontology supplies the category match.', alternative: 'The phrase by train allows agent, conveyance, or location roles. Background knowledge classifies train as a conveyance. The compatible role fills the conveyance slot of the travel frame.', nodes: [['“by train”', 'A cue from the actual sentence.'], ['Candidate roles', 'By permits agent, conveyance, or location in the example.'], ['Conveyance slot: train', 'Background knowledge of trains selects the compatible role.']], edges: [[0, 1, 'preposition constraints'], [1, 2, 'ontology match']] }],
    synthesis: 'Understanding is not just assigning parts of speech. It combines event structure, grammatical constraints, and background knowledge to build an interpretation from which appropriate inferences can be drawn.',
  },
  15: {
    summary: 'Commonsense reasoning represents related meanings with primitive actions and connects actions to implied events and state changes.',
    sections: [
      { id: 'primitives', title: 'Different words can describe the same underlying action', sourceSection: 'Example Ashok Ate a Frog; Primitive Actions', pages: [201, 203], text: 'The earlier understanding lesson asked how one word can have different meanings. This lesson asks the converse: how different words can convey a similar event. Ate, consumed, and ingested can share an ingestion interpretation in an appropriate context, even if their connotations differ.\n\nPrimitive actions provide a common internal vocabulary for such interpretations. The book includes move-object, move-possession, ingest, propel, speak, and other primitives. Move-object concerns physical movement; move-possession concerns a transfer of possession. Their distinction matters: changing who has a book and moving a book through space are not identical descriptions. Each primitive has a frame of roles and relevant expectations.' },
      { id: 'processing', title: 'Retrieve a primitive frame and fill its roles', sourceSection: 'Thematic Roles and Primitive Actions; Exercise Roles Primitive Actions', pages: [204, 206], text: 'In the cart example, the verb supplies a cue to retrieve a propel frame. Rules associated with slots use lexical categories and sentence position to find the agent and object. For transfer of a book, a from phrase supplies a source and background knowledge identifies the participants.\n\nBottom-up cues trigger top-down expectations; lexical, syntactic, and semantic analysis cooperate. If a candidate primitive frame fits poorly, the agent may have to reconsider it rather than force every word into the wrong slots. This structured representation supports questions such as who now has an object and who had it before.' },
      { id: 'implied', title: 'An action can be implied rather than named directly', sourceSection: 'Implied Actions; Actions and Subactions; State Changes; Implied Actions and State Changes', pages: [206, 208], text: '“Fertilized the field” can be interpreted through an implied movement of fertilizer onto the field, even though the sentence does not directly name the lower-level movement. Background knowledge supplies a decomposition that maps more readily to primitive actions.\n\nActions can have subactions and change states. A sentence may emphasize the event, its result, or an attitude toward it. The representation must distinguish what was performed from what state resulted or was desired. An inferred consequence depends on the modeled action and context; it must not be asserted merely because two sentences share a word.' },
      { id: 'composition', title: 'Connect action frames and resultant states', sourceSection: 'Actions and Resultant Actions; Exercise State Changes; Wrap Up; The Cognitive Connection', pages: [209, 211], text: 'Sentences with multiple verbs can require multiple linked frames: deciding to act, communicating an instruction, performing an action, or enjoying an event are not one undifferentiated verb. Connections among action and state-change frames make the interpretation explicit.\n\nThe lesson’s cognitive connection extends beyond physical movement to goals, beliefs, and desires used in social interpretation. It is an introductory representation account, not a complete inventory of all commonsense knowledge. Scripts next combine primitive-event frames into longer, familiar sequences.' },
    ],
    sketches: [{ after: 'primitives', title: 'Possession change is distinct from location change', pages: [202, 206], caption: 'Original schematic of the book’s primitive distinction. A possession-transfer frame answers who had and who has the object.', alternative: 'The book is initially possessed by Mary. A move-possession action transfers it to John. The representation records source Mary, object book, and recipient John; this is not merely a geometric movement.', nodes: [['Mary has book', 'Source of possession before the action.'], ['Move-possession', 'Object: book; source: Mary; recipient: John.'], ['John has book', 'Resulting possession in the event interpretation.']], edges: [[0, 1, 'source'], [1, 2, 'recipient/result']] }],
    synthesis: 'Primitive actions abstract across surface wording while linked frames represent roles, implied subevents, and consequences. The abstraction supports commonsense interpretation, but its inferences still require appropriate background knowledge.',
  },
  16: {
    summary: 'Scripts represent familiar, causally coherent sequences of events. They connect frames across a story and generate expectations that can be violated.',
    sections: [
      { id: 'parts', title: 'A script is structured knowledge about an event sequence', sourceSection: 'Story Understanding for AI Agents; Visiting a Coffeehouse; Definition of Scripts; Parts of a Script', pages: [213, 215], text: 'A script captures a causally coherent set of events, not just one sentence or an unordered collection of facts. The coffeehouse example is understandable because the reader knows what typically follows arriving, ordering, paying, and receiving a drink. Some unstated events can be inferred from that familiar structure.\n\nThe six parts are entry conditions, results, props, roles, tracks, and scenes. Entry conditions describe when the script applies; results describe its expected outcome; props are involved objects; roles are participants; tracks are variations; scenes organize event sequences. These parts supply both a representation of a typical situation and expectations about its progression.' },
      { id: 'restaurant', title: 'Instantiate scenes rather than treating the stereotype as the event', sourceSection: 'Constructing a Script; Form vs Content', pages: [215, 217], text: 'The restaurant script describes roles such as customer and waiter, props such as menus and food, and scenes such as entering, ordering, eating, and paying. A particular visit fills those variables with particular people and objects. Primitive-action frames represent the component events within the scenes.\n\nThe general script and its current instance are distinct. The stored structure can help an agent choose what to do without constructing a new plan from scratch, but only where the situation fits the script. The restaurant sequence is a contextual stereotype, not a universal rule for every culture or establishment.' },
      { id: 'expectations', title: 'Surprise reveals a failed expectation or an unexpected event', sourceSection: 'Using a Script to Generate Expectations; Tracks', pages: [217, 218], text: 'Waiting for a menu that never arrives is an expectation violation. Receiving a bill before ordering is an unexpected event. Both are recognizable because the script predicted a different progression. Identifying the scene where the mismatch occurs gives the agent a more specific problem than simply declaring the whole story confusing.\n\nTracks distinguish variations such as coffeehouse, fast food, and formal dining. Observed cues help classify the situation into the appropriate track. The agent may refine its choice as more evidence arrives rather than insist that every restaurant follow its first selected sequence.' },
      { id: 'learning', title: 'Learning and using scripts are different tasks', sourceSection: 'Exercise Learning a Script; Exercise Using a Script; Wrap Up; The Cognitive Connection', pages: [219, 222], text: 'Learning a script abstracts recurring event structure; using one retrieves and instantiates that structure for a new situation. Frames and semantic networks provide representational components. Concept learning can distinguish tracks, planning can provide a sequence worth retaining, and commonsense primitives provide a vocabulary for the events.\n\nClassification selects a suitable script; understanding interprets the current story; decomposition can locate an obstruction within a scene. The cognitive connection emphasizes the combination of top-down prediction and bottom-up correction. Fast routine understanding is possible because much structure is already stored, not because unfamiliar or exceptional events need no reasoning.' },
    ],
    sketches: [{ after: 'restaurant', title: 'A restaurant script links scenes', pages: [215, 217], caption: 'Original simplified scene schematic. Roles, props, entry conditions, and results belong to the surrounding script; tracks can alter the sequence.', alternative: 'Under the appropriate restaurant track, a customer enters, orders, eats, and pays. Each scene contains primitive-event frames and creates expectations for what follows. A particular visit fills in participants and objects.', nodes: [['Enter', 'Locate the restaurant and take the place appropriate to the track.'], ['Order', 'Customer and staff exchange information about food.'], ['Eat', 'Food is received and consumed.'], ['Pay and leave', 'Payment and departure complete this simplified track.']], edges: [[0, 1, 'next scene'], [1, 2, 'food arrives'], [2, 3, 'complete visit']] }],
    synthesis: 'Scripts make longer stories understandable through stored event structure. They save repeated planning, but their predictions must remain responsive to the actual track and unexpected events.',
  },
  17: {
    summary: 'Explanation-based learning abstracts relevant causal knowledge from known concepts and transfers it to explain a new instance.',
    sections: [
      { id: 'explanation', title: 'Use prior knowledge to explain a novel use', sourceSection: 'Exercise Transporting Soup; Example Retrieving a Cup; Concept Space; Prior Knowledge', pages: [224, 226], text: 'The soup and cup examples ask how an agent recognizes an unfamiliar object as suitable when its usual utensil is unavailable. Explanation-based learning does not simply collect many new examples or invent a concept from nothing. It connects existing conceptual knowledge to establish why the new instance satisfies a needed description.\n\nPrior knowledge includes causal fragments: a brick is stable because it has a flat bottom; a bowl carries liquid because it is concave; a briefcase is liftable because it is light and has a handle; a glass enables drinking because it carries liquid and is liftable. These are the source’s simplified domain relationships. Incidental decoration or unrelated attributes need not participate in the explanation.' },
      { id: 'transfer', title: 'Abstract the causal relationship, then transfer it', sourceSection: 'Abstraction; Transfer', pages: [226, 229], text: 'Abstraction replaces the particular source object with a variable or general object while retaining the relationship needed for the explanation. The useful knowledge from the bowl is not its name or contents, but the modeled connection from concavity to carrying liquid.\n\nTo show the new object is a cup under the given definition, work backward from stable and enables-drinking. Stability is supported by the flat-bottom fragment. Enabling drinking requires carrying liquid and being liftable, supported by the bowl and briefcase fragments. Their effects become conditions in the glass fragment. The agent composes those explanations and checks their conditions against the new object. This is goal-directed retrieval of relevant knowledge, not indiscriminate transfer of every property of a source.' },
      { id: 'gap', title: 'An explanation must not jump over a missing link', sourceSection: 'Exercise Explanation-Based Learning I; Exercise Explanation-Based Learning II; Wrap Up', pages: [229, 231], text: 'The mug example adds the requirement protects-against-heat. A known pot fragment says thick clay sides limit heat transfer, but initially there is no link from limiting heat transfer to protection against heat. The other cup conditions can be established, yet the complete mug explanation cannot be made from that knowledge alone.\n\nThe missing relationship identifies what additional knowledge is needed. Similar-sounding phrases are not automatically interchangeable predicates. This is a limitation and a learning opportunity: reasoning specifies a precise gap instead of filling it with an unsupported assertion.' },
    ],
    sketches: [{ after: 'transfer', title: 'A cup explanation depends on intermediate properties', pages: [228, 228], caption: 'Original schematic of the source’s simplified cup definition. Structural conditions support functional properties; those properties support the classification.', alternative: 'Concavity supports carrying liquid. Lightness and a handle support liftability. Carrying liquid and liftability support enabling drinking. A flat bottom supports stability. Stability and enabling drinking support the cup description in this model.', nodes: [['Structural conditions', 'Concavity; lightness and handle; flat bottom.'], ['Functional properties', 'Carries liquid; liftable; stable.'], ['Cup in the given model', 'Requires stability and enabling drinking, with drinking supported by carrying liquid and liftability.']], edges: [[0, 1, 'causal fragments'], [1, 2, 'compose explanation']] }],
    synthesis: 'Explanation-based learning finds what prior knowledge is relevant, abstracts it, and composes a justified transfer. A missing causal connection remains an explicit gap rather than a plausible-sounding conclusion.',
  },
  18: {
    summary: 'Analogical reasoning retrieves a source by meaningful similarity, maps corresponding roles, and transfers a relational pattern across domains before evaluation.',
    sections: [
      { id: 'similarity', title: 'Similar objects and similar relationships are different evidence', sourceSection: 'Exercise Similarity Ratings; Cases Revisited; Need for Cross-Domain Analogy; Spectrum of Similarity', pages: [234, 237], text: 'A woman climbing a ladder and a woman painting a ladder share objects but differ in the relevant relation. An ant climbing a wall shares less surface appearance but a relation of ascent. Analogical reasoning can use such relational similarity to understand a target problem through a familiar source, including across domains.\n\nRecording cases and case-based reasoning are within-domain forms of reuse. Cross-domain analogy additionally needs to determine which different objects play corresponding roles. The textbook’s fortress-and-radiation thought experiment illustrates transfer of a convergence strategy through shared resource, obstacle, and goal relations. It is a cognitive-science example, not a medical treatment recommendation.' },
      { id: 'retrieval', title: 'Retrieve by the kind of similarity that matters', sourceSection: 'Process of Analogical Reasoning; Analogical Retrieval; Three Types of Similarity', pages: [237, 240], text: 'The described process has retrieval, mapping, transfer, evaluation, and storage. Retrieval must notice deeper relationships rather than rely only on object names, feature values, or counts. Higher-order relationships can connect the relations themselves, such as how an obstacle prevents a resource from achieving a goal.\n\nSemantic similarity concerns concepts; pragmatic similarity concerns goals and other task-related considerations; structural similarity concerns relationships in the representations. These are not interchangeable measures. Different tasks or theories may weight them differently. Structural similarity is about representational organization, not just two objects having a similar physical outline.' },
      { id: 'mapping', title: 'Map roles before transferring a solution', sourceSection: 'Analogical Mapping; Exercise Analogical Mapping; Analogical Transfer; Exercise Analogical Transfer', pages: [241, 244], text: 'Mapping solves the correspondence problem: what in the source matches what in the target? In the fortress example, the resource corresponds to the resource and the obstacle to the obstacle. Superficially matching two people would miss the goal structure. In the historical solar-system/atom model, center and revolving-object roles constrain a mapping that object properties alone leave ambiguous.\n\nTransfer abstracts a source relationship or strategy and instantiates it using that mapping. It is selective, not a claim that the target inherits every source property. The atomic example is a simplified historical teaching model for correspondence, not a complete physical account of atoms. A convincing mapping can still propose an incorrect target solution, so evaluation remains necessary.' },
      { id: 'design', title: 'Design analogy can compose sources and revise itself', sourceSection: 'Evaluation and Storage in Analogical Reasoning; Design by Analogy; Design by Analogy Retrieval; Design by Analogy Mapping Transfer; Design by Analogy Evaluation Storage; Advanced Open Issues in Analogy', pages: [244, 249], text: 'The biologically inspired design discussion uses models of structure, behavior, and function, not merely visual resemblance. A water-walking organism supplies knowledge about how its structure achieves locomotion; mapping and transfer can proceed through these levels to a proposed robot design.\n\nCompositional analogy can build up a transfer through related levels of a model. Compound analogy combines useful parts from multiple sources, as in the low-speed and high-speed swimming examples. Simulation or prototyping may reveal failure and send the process back to mapping, transfer, or retrieval. The target problem itself can evolve as a partial design exposes a new requirement. Common vocabulary, selecting relevant knowledge, and combining sources remain difficult questions rather than solved guarantees.' },
    ],
    sketches: [{ after: 'mapping', title: 'Correspondence guides selective transfer', pages: [241, 243], caption: 'Original schematic of cross-domain reasoning. Role mapping must precede the proposed transfer; evaluation checks the resulting target solution.', alternative: 'A source model and a target model are aligned by their relations and roles. A source strategy is abstracted and instantiated through the mapping. The resulting target proposal must be evaluated rather than accepted from similarity alone.', nodes: [['Source and target models', 'Represent the relevant roles, relations, and goals.'], ['Correspondence mapping', 'Align roles using relational structure.'], ['Transferred proposal', 'Instantiate the useful source pattern in the target.'], ['Evaluation', 'Check the proposal against target requirements.']], edges: [[0, 1, 'align relations'], [1, 2, 'selective transfer'], [2, 3, 'test target fit']] }],
    synthesis: 'Analogy is a knowledge-guided transfer process, not resemblance as proof. Retrieval finds a promising source, mapping establishes roles, transfer proposes an answer, and evaluation determines whether it works.',
  },
  19: {
    summary: 'Version spaces retain consistent concept hypotheses between specific and general boundaries. Identification trees offer another organization of labeled examples, trading incremental arrival for batch feature selection.',
    sections: [
      { id: 'boundaries', title: 'Keep alternatives instead of committing to one description', sourceSection: 'Incremental Concept Learning Revisited; Abstract Version Spaces; Visualizing Version Spaces', pages: [252, 256], text: 'The earlier concept learner revised one current description using carefully informative examples and background knowledge. Version-space learning instead tracks possible descriptions consistent with the examples, bounded by specific and general models. It addresses how far to generalize when the order of examples is not controlled and background categories may be unavailable.\n\nThe specific side covers the observed positives as narrowly as the hypothesis form permits. The general side remains as broad as the evidence allows while excluding negatives. They are boundaries of the remaining possibilities, not a claim that one initial guess is already correct. Multiple alternatives can persist until later examples discriminate among them.' },
      { id: 'example', title: 'The meal example narrows both sides', sourceSection: 'Example Food Allergies I; Example Food Allergies II; Example Food Allergies III; Example Food Allergies IV; Example Food Allergies V; Version Spaces Algorithm', pages: [256, 261], text: 'The book’s invented meal records use restaurant, meal, day, and cost with a positive or negative reaction label. The first positive record creates a specific description of that visit and a completely general alternative. A negative record specializes the general alternatives to exclude it without excluding the positive. A further positive generalizes the specific description and removes general alternatives that cannot cover it.\n\nWith the complete illustrated sequence, the surviving description is cheap meals at Sam’s. Intermediate hypotheses such as all meals at Sam’s remain until a discriminating example eliminates them. Pruning removes inconsistent models and redundant boundary models subsumed by retained ones. Negative examples must be excluded, not “included” as a damaged transcript sentence suggests. These are teaching data about hypothesis revision, not an actual allergy diagnosis.' },
      { id: 'limits', title: 'Convergence depends on evidence and hypothesis form', sourceSection: 'Version Spaces Algorithm; Exercise Version Spaces VI; Wrap Up', pages: [260, 267], text: 'Informative positive and negative examples can bring the specific and general boundaries together. For the illustrated representable concept, the consistent final result does not depend on the order of those examples. A lack of discriminating evidence can leave several hypotheses; an insufficient description language can prevent a satisfactory concept from being represented at all.\n\nThe lesson notes that reactions to multiple combinations, such as different meals at different restaurants, can defeat the simple hypothesis form. More records do not repair an unexpressible distinction. More features and examples also demand more computation. Convergence therefore must not be read as an unconditional promise that any dataset eventually yields the true concept.' },
      { id: 'trees', title: 'Identification trees choose features to separate labels', sourceSection: 'Identification Trees; Optimal Identification Trees', pages: [264, 266], text: 'An identification or decision tree organizes labeled examples by feature questions. The meal example first separates restaurants, then separates the remaining mixed group by cost, until leaves have a consistent label. The sunburn illustration compares feature orders that yield shorter or bushier trees on the given data.\n\nUnlike incrementally adding a discrimination question when a new stored case collides with an old one, this discussion chooses questions with the batch of examples available. The tradeoff is up-front data versus a more economical classification tree for those examples. The examples illustrate feature selection; they do not prove a greedy question choice always constructs the globally optimal tree or that a training correlation is a causal law.' },
    ],
    sketches: [{ after: 'boundaries', title: 'Positive and negative examples constrain different boundaries', pages: [253, 254], caption: 'Original schematic of version-space constraints. Remaining hypotheses must cover positives and exclude negatives; convergence requires sufficient discriminating evidence.', alternative: 'Positive examples require the specific boundary to generalize and inconsistent general candidates to be removed. Negative examples require general candidates to specialize or be removed. The remaining consistent hypotheses lie between the boundaries.', nodes: [['Positive examples', 'All retained hypotheses must cover these examples.'], ['Consistent hypotheses', 'Alternatives remain between specific and general boundaries.'], ['Negative examples', 'All retained hypotheses must exclude these examples.']], edges: [[0, 1, 'require coverage'], [2, 1, 'require exclusion']] }],
    tables: [{ after: 'example', title: 'The five source visits and their hypothesis changes', sourceSection: 'Example Food Allergies I; Example Food Allergies II; Example Food Allergies III; Example Food Allergies IV; Example Food Allergies V', pages: [256, 260], columns: ['Visit and label', 'Observed features: restaurant / meal / day / cost', 'Change to the surviving descriptions'], rows: [
      ['1: positive', "Sam’s / breakfast / Friday / cheap", "Specific: [Sam’s, breakfast, Friday, cheap]. General: [any, any, any, any]."],
      ['2: negative', "Kim’s / lunch / Friday / expensive", "General alternatives require Sam’s, breakfast, or cheap. A Friday-only alternative is rejected: it also covers this negative."],
      ['3: positive', "Sam’s / lunch / Saturday / cheap", "Specific becomes [Sam’s, any, any, cheap]. Remove breakfast-only from the general alternatives because it misses this positive."],
      ['4: negative', "Bob’s / breakfast / Sunday / cheap", "Cheap-only is insufficient. After specialization and subsumption, all-Sam’s still survives; the specific side still requires Sam’s + cheap."],
      ['5: negative', "Sam’s / breakfast / Sunday / expensive", "All-Sam’s must specialize to cheap. Both boundaries now give [Sam’s, any, any, cheap]."],
    ] }],
    synthesis: 'Version spaces make uncertainty among concept descriptions explicit. Decision trees organize discrimination differently. Both are constrained by the chosen features, labeled evidence, and representational capacity.',
  },
  20: {
    summary: 'Constraint propagation uses local restrictions to seek globally compatible interpretations. Line labeling and grammar show how assigning one value constrains neighboring choices without always producing a unique answer.',
    sections: [
      { id: 'variables', title: 'Variables, values, and constraints define interpretation', sourceSection: 'Exercise Recognizing 3D Figures; Exercise Gibberish Sentences; Constraint Propagation Defined', pages: [269, 271], text: 'Constraint propagation assigns values to variables so that relevant conditions are satisfied together. A local assignment can rule out choices elsewhere. The lesson’s recognition examples ask how a two-dimensional drawing can represent surfaces of a three-dimensional object, or how words can form a grammatical sentence.\n\nA grammatical sentence need not make semantic sense. The deliberately nonsensical language examples separate satisfying grammar from understanding a plausible event. Similarly, a drawing can admit more than one coherent spatial interpretation. Constraints may leave several assignments or no assignment; they are not automatically a unique-answer mechanism.' },
      { id: 'labels', title: 'Line labeling turns junction knowledge into edge restrictions', sourceSection: 'From Pixels to 3D; Line Labeling; Constraints Intersections and Edges', pages: [272, 274], text: 'The visual task is decomposed into detecting lines, grouping them into oriented surfaces, and recognizing a three-dimensional object. The lesson concentrates on the middle step. A fold is an edge where two surfaces meet; a blade is an edge where that two-surface relationship is not inferred in the simplified scheme.\n\nPrior knowledge specifies allowable label combinations for Y, W, L, and T junctions in the trihedral-object illustration. Its simplified Y junction has three folds; an L has two blades; a W has blade–fold–blade; the printed T rule has two blades and a fold. These are the teaching ontology’s selected patterns, not universal rules for every image. Assigning a shared edge’s label at one junction constrains which patterns are possible at the junction at its other end.' },
      { id: 'propagation', title: 'Propagate shared-edge consistency, then inspect conflicts', sourceSection: 'Exercise Assembling the Cube I; Exercise Assembling the Cube II; More Complex Images', pages: [274, 276], text: 'Identify the cube drawing’s junction types, apply their permitted labels, and carry an edge’s label to adjacent junctions. A fold implies meeting surfaces; compatible labels across the drawing support grouping lines into the cube’s surfaces. The local junction rules thus contribute to a global interpretation.\n\nA more complex image exposes the limited ontology: a line may be treated as a fold from one starting point and a blade from another, or may merely be a line drawn on a surface. The book explains that a richer set of junction constraints is needed. Richer constraints can also permit multiple consistent interpretations. A conflict is a reason to inspect the assumptions and representation, not arbitrarily erase the inconvenient label.' },
      { id: 'grammar', title: 'The same inference idea applies to grammatical structure', sourceSection: 'Constraint Propagation for Natural Language Processing; Wrap Up; The Cognitive Connection', pages: [276, 279], text: 'Words are assigned lexical categories and grouped into phrases under grammar constraints. In the example, a noun phrase contains adjectives and a noun, while a verb phrase contains a verb and an optional adverb. Candidate phrase divisions must agree with lexical information and the grammar.\n\nTop-down structural expectations and bottom-up word classifications support one another. A successful parse establishes grammatical compatibility, not that its nonsensical content is true or meaningful. Further semantic interpretation can use that structure. Across language and vision, constraint propagation is a general inference method whose results depend on the particular constraints supplied.' },
    ],
    sketches: [{ after: 'propagation', title: 'A shared edge connects two local constraints', pages: [273, 275], caption: 'Original schematic of propagation, not a reproduced junction diagram. A label cannot be chosen independently at the two ends of the same edge.', alternative: 'A permitted pattern at junction A labels shared edge e as a fold. Junction B must use a permitted pattern compatible with e being a fold. That choice constrains B’s other incident edges, propagating information through the image.', nodes: [['Junction A pattern', 'A local permitted pattern gives edge e a fold label.'], ['Shared edge e: fold', 'The edge has one consistent interpretation at both ends.'], ['Junction B patterns', 'Keep patterns compatible with e; constrain B’s other edges.']], edges: [[0, 1, 'assign label'], [1, 2, 'restrict neighbors']] }],
    synthesis: 'Constraint propagation connects local possibilities through shared variables and structural rules. The book’s visual and grammatical examples show both its power and why compatibility can be ambiguous or fail under an inadequate ontology.',
  },
  21: {
    summary: 'Configuration is routine design with known components and constrained choices. Plan refinement assigns values at successive levels and evaluates the resulting arrangement.',
    sections: [
      { id: 'task', title: 'Configuration is a design task, not one particular algorithm', sourceSection: 'Define Design; Exercise Designing a Basement; Defining Configuration', pages: [280, 282], text: 'Design turns needs, goals, or functions into a specification of an artifact. In open-ended design, the problem and solution can evolve together. Configuration is the more routine case: the components or available component types are known, and the task is to assign their variables and arrange them under constraints.\n\nThe basement example distinguishes satisfying numerical area totals from producing a spatial layout that actually fits. A set of individually plausible room sizes is not necessarily a valid arrangement. Variable-order heuristics may begin with the most restricted, most influential, or most important choices, but those are control choices within the task rather than its definition.' },
      { id: 'refinement', title: 'Refine a skeletal plan into a complete arrangement', sourceSection: 'The Configuration Process; Example Representing a Chair; Example Ranges of Values', pages: [283, 285], text: 'The illustrated method begins with a high-level design plan. Assign values to its variables, then refine and expand it into a more detailed plan with additional variables. Continue through an abstraction hierarchy until the arrangement is specified. Evaluation may return the process to earlier choices or expose an additional requirement.\n\nA chair frame links to component frames for legs, seat, arms, and back. Variables include count, size or mass, material, and cost with allowed ranges. The source uses simplified gram-based sizes to make mass and material-cost calculations easy; these are teaching quantities, not realistic furniture specifications.' },
      { id: 'constraints', title: 'Global constraints restrict component choices', sourceSection: 'Example Applying a Constraint; Exercise Applying a Constraint', pages: [286, 288], text: 'A global cost or mass requirement must be distributed or checked across components. The sample plan allocates a cost allowance to parts, preserves an explicitly requested leg count, chooses allowed sizes and materials, then computes the aggregate result. Another plan may choose material first instead of cost; there is no single mandatory variable order.\n\nConstraints propagate through the plan hierarchy. A component change can affect the total cost or mass and require revision elsewhere. The final arrangement must be evaluated against the whole specification, not accepted because each slot has some value. Changing the specification is a design decision, not a silent way to count an invalid arrangement as a solution.' },
      { id: 'connections', title: 'Plan refinement, classification, and case adaptation differ', sourceSection: 'Connection to Classification; Contrast with Case-Based Reasoning; Connection to Planning', pages: [288, 290], text: 'Refinement resembles establish-and-refine classification, but adds increasingly detailed component variables and their constraints. A planning process can generate a skeletal sequence or structure that configuration later instantiates.\n\nCase-based design instead retrieves an existing arrangement and adapts it. Plan refinement starts from a plan abstraction hierarchy. Both can address routine design, and other reasoning methods may also be used. The task/method distinction explains why configuration should not be treated as a synonym for constraint propagation or for case-based reasoning.' },
    ],
    sketches: [{ after: 'refinement', title: 'A design plan acquires detail through refinement', pages: [283, 285], caption: 'Original schematic of plan refinement. Known component structure is expanded while values are constrained and the final arrangement is checked.', alternative: 'Start with overall chair requirements. Refine to component choices for legs, seat, arms, and back. Assign count, size, material, and cost within allowed ranges. Check the combined arrangement against overall constraints.', nodes: [['Overall requirements', 'Global constraints and a high-level plan.'], ['Component plans', 'Expand the known chair components.'], ['Assigned component variables', 'Choose permitted values for their slots.'], ['Arrangement model', 'Evaluate aggregate cost, mass, and other requirements.']], edges: [[0, 1, 'refine'], [1, 2, 'assign values'], [2, 3, 'evaluate whole']] }],
    synthesis: 'Configuration combines known structure with constrained instantiation. A valid arrangement requires compatible component choices and satisfaction of global requirements, not merely a filled-in frame.',
  },
  22: {
    summary: 'Diagnosis explains a discrepancy between expected and observed behavior. It maps data to fault hypotheses, compares competing explanations, and uses tests and repair feedback to refine them.',
    sections: [
      { id: 'task', title: 'Find the fault responsible for a malfunction', sourceSection: 'Exercise Diagnosing Illness; Defining Diagnosis', pages: [293, 294], text: 'Diagnosis begins when observed behavior differs from expected behavior. The task is to identify the fault or faults responsible. Rules, past cases, or a model of how the system works can support that task; diagnosis is not itself just one of those methods.\n\nThe lesson uses fictional disease names and abstract data letters to make competing explanations visible. Those examples are not health advice. Car and computer examples show the same task in other domains: explain the discrepancy, rather than merely attach a label to any observed symptom.' },
      { id: 'spaces', title: 'Data and hypotheses have a many-to-many relationship', sourceSection: 'Data Space and Hypothesis Space; Problems with Diagnosis as Classification', pages: [295, 297], text: 'The data space contains observations and their abstractions. The hypothesis space contains candidate faults and their refinements. Bottom-up abstraction can organize observations, while top-down refinement can specialize a candidate explanation. The lesson calls their combination heuristic classification.\n\nOne observation may have several possible explanations, and one hypothesis may explain several observations. Hypotheses also predict further data worth collecting. Mutual exclusion means two hypotheses cannot both hold in the modeled situation; cancellation means combined effects can mask an expected observation. A diagnosis cannot therefore be chosen by matching one symptom to one label independently of the rest.' },
      { id: 'abduction', title: 'Diagnosis is abductive, not the converse of a deduction', sourceSection: 'Deduction, Induction, Abduction', pages: [298, 299], text: 'Deduction uses a rule and its antecedent to derive a consequence. Induction generalizes a rule from observed relationships. Abduction uses an observed consequence and relevant knowledge to propose an explanation. A cause-to-effect implication does not license certainty about the cause when its effect is observed.\n\nDifferent faults can produce the same behavior, so an abductive conclusion is a hypothesis rather than a truth-preserving deduction. An agent may combine abduction with deduction to predict additional observations and induction to revise relationships. Keeping these directions distinct prevents an explanatory guess from masquerading as a proof.' },
      { id: 'criteria', title: 'Balance coverage, parsimony, and confidence', sourceSection: 'Criteria for Choosing a Hypothesis; Exercise Diagnosis as Abduction', pages: [299, 301], text: 'Explanatory coverage asks how much of the relevant data an explanation accounts for. Parsimony prefers a simpler explanation when other considerations are comparable. Confidence favors hypotheses supported more strongly or regarded as more likely. These can conflict: a single hypothesis may be simple but leave data unexplained, while a larger set covers more data at a cost.\n\nThe fictional examples combine hypotheses when needed and account for interactions that cancel effects. The goal is a coherent explanation of the whole observation set, not simply the fewest labels or the largest raw count of matching items. The source presents these as selection criteria, not a quantified probability formula.' },
      { id: 'feedback', title: 'Testing and repair feed new evidence back into diagnosis', sourceSection: 'Completing the Process; Wrap Up', pages: [301, 302], text: 'A proposed fault can suggest additional observations or tests. Once a diagnosis is selected, it indexes a treatment or repair plan. Monitor the result: if replacing a suspected part does not restore the expected behavior, that failure becomes new diagnostic evidence.\n\nDiagnosis therefore loops among data collection, hypotheses, and intervention rather than ending at the first plausible explanation. Repair and diagnosis remain different tasks. Restoring behavior can support an explanation, while failed intervention can reveal incomplete or mistaken assumptions.' },
    ],
    sketches: [{ after: 'feedback', title: 'A hypothesis guides the next observation', pages: [295, 301], caption: 'Original diagnostic feedback schematic. An explanation is provisional; predictions and repair outcomes can require its revision.', alternative: 'Observed discrepancy supports candidate fault hypotheses. A hypothesis predicts additional observations and guides tests. Results return to the data used to assess the hypotheses. A repair outcome also becomes evidence, not an automatic confirmation.', nodes: [['Observed discrepancy', 'Expected and actual behavior differ.'], ['Fault hypotheses', 'Candidate explanations with possible interactions.'], ['Tests and predictions', 'Collect evidence that distinguishes candidates.']], edges: [[0, 1, 'abduce explanation'], [1, 2, 'predict evidence'], [2, 0, 'new observations']] }],
    synthesis: 'Diagnosis reasons from effects toward possible causes while checking competing explanations. Coverage, simplicity, and confidence guide selection; new observations and repair outcomes keep that selection accountable.',
  },
  23: {
    summary: 'Learning by correcting mistakes isolates a suspicious knowledge feature, explains its role in failure, and repairs the model without damaging other valid knowledge.',
    sections: [
      { id: 'failure', title: 'A wrong answer starts learning; it does not finish it', sourceSection: 'Exercise Identifying a Cup; Questions for Correcting Mistakes', pages: [305, 307], text: 'A robot classifies a pail as a cup and receives corrective feedback. It must identify the error, explain why that error led to the failure, and repair its knowledge. A mistaken rejection of a genuine cup poses the complementary problem. Both over-inclusion and under-inclusion can require revision.\n\nBlame assignment identifies what in knowledge, reasoning, or architecture was responsible. This lesson concentrates on classification knowledge. A failed outcome alone does not reveal which of many distinguishing features caused it. Self-diagnosis makes this a step toward metacognition rather than merely diagnosis of another system.' },
      { id: 'suspicion', title: 'Contrast examples to find suspicious features', sourceSection: 'Visualizing Error Detection; Error Detection Algorithm', pages: [307, 309], text: 'A false success is something the agent accepted that should not have been accepted; a true success was correctly accepted. Features shared with correct cases are less useful for isolating why an accepted pail was wrong. Comparing more examples can eliminate incidental differences such as color.\n\nThe printed algorithm identifies suspicious false-success relations by intersecting features of the false successes and removing the union of true-success features. The complementary displayed calculation intersects true-success features and removes the union of false-success features. These operations identify contrasts in the supplied examples; they do not by themselves establish causality or guarantee that the representation contains the needed feature. The transcript mixes up these unions and intersections, so the printed algorithm is the locator for this summary.' },
      { id: 'explanation', title: 'A repaired classification must preserve the right explanation', sourceSection: 'Explanation-Free Repair; Explaining the Mistake; Discussion Correcting the Mistake; Correcting the Mistake', pages: [309, 311], text: 'Adding “handle is fixed” to the cup rule can exclude the pail, but an unexplained extra condition does not say why it matters. The causal explanation locates the condition: a fixed handle supports manipulating and orienting the object for drinking, not liftability in general.\n\nPlacing the requirement under liftable would incorrectly deny that a pail or a briefcase with a movable handle can be lifted. The repair must therefore preserve valid background knowledge while changing the mistaken connection. The example shows why patching a decision rule and repairing its explanatory model are not equivalent.' },
      { id: 'learning', title: 'Action feedback connects concept revision to reasoning', sourceSection: 'Connection to Incremental Concept Learning; Wrap Up; The Cognitive Connection', pages: [312, 314], text: 'Like incremental concept learning, corrective learning revises knowledge using examples. Here the agent’s own decision and the feedback it receives determine the learning need. Explanation connects the suspicious feature to the failure and guides a targeted repair.\n\nThe agent uses memory and reasoning to diagnose its model, then learns a change intended to improve future action. This is not a license to overfit one failure with arbitrary conditions. Additional examples and consistency with earlier explanations are essential when several candidate repairs remain.' },
    ],
    sketches: [{ after: 'explanation', title: 'Repair the drinking condition, not all liftability', pages: [310, 311], caption: 'Original schematic of the source’s corrected explanation. A movable handle does not imply that an object cannot be lifted.', alternative: 'An object may be liftable with either a fixed or movable handle. In the cup example’s corrected model, the fixed-handle condition supports manipulability for drinking. Put the new condition on that explanatory connection, not on general liftability.', nodes: [['Liftable object', 'The pail counterexample preserves this property.'], ['Manipulable for drinking', 'The corrected cup explanation includes the fixed-handle condition here.'], ['Enables drinking', 'Supported by relevant properties rather than a false restriction on all lifting.']], edges: [[0, 1, 'relevant but not enough'], [1, 2, 'corrected support']] }],
    synthesis: 'Correcting a mistake requires more than recording that it was wrong. The agent must isolate what matters, explain the failure, and revise the relevant knowledge without discarding valid distinctions.',
  },
  24: {
    summary: 'Meta-reasoning examines the agent’s own knowledge and processes, identifies errors or gaps, and selects or integrates methods to meet a task.',
    sections: [
      { id: 'gaps', title: 'Errors and missing knowledge need different responses', sourceSection: 'Mistakes in Reasoning and Learning; Beyond Mistakes Knowledge Gaps; The Blurred Line Between Cognition and Metacognition', pages: [316, 318], text: 'Meta-reasoning reasons about the agent’s own knowledge, reasoning, or learning. An incorrect connection needs repair; an absent connection needs acquisition. The mug explanation’s missing link from heat-transfer limitation to protection against heat is a knowledge gap, not evidence that every existing fragment is wrong.\n\nDetecting that gap creates a learning goal: find knowledge that can connect the required conditions, whether from memory or an external source. A reasoning impasse can likewise create a goal to find a different method. Deliberation and metacognition can overlap; the crucial questions are what the process is acting on and what knowledge it uses, not forcing every operation into a disjoint box.' },
      { id: 'selection', title: 'Select a method using its requirements and consequences', sourceSection: 'Strategy Selection', pages: [319, 319], text: 'An agent may know several methods. Selection depends first on whether the required knowledge is available: cases for case-based reasoning, constraints for constraint propagation, or appropriate formal premises for logic. A method name does not make its missing knowledge appear.\n\nWhere multiple methods apply, computational efficiency and solution quality can matter. A close prior case may favor reuse; interacting goals can undermine a simple difference heuristic. The discussion also distinguishes incremental example arrival from batch data when choosing a learning method. Quality claims remain conditional on the method’s domain and assumptions, not an unconditional guarantee attached to a label.' },
      { id: 'integration', title: 'Integrate methods across a task and its subtasks', sourceSection: 'Strategy Integration; Process of Meta-Reasoning', pages: [320, 321], text: 'Selecting a method for the overall task does not prescribe every subtask’s method. Case-based reasoning can use rules, a model, or recursive retrieval for adaptation. A blocks-world obstacle can prompt problem reduction and then return to means-ends analysis on a selected subproblem.\n\nMeta-reasoning can itself use familiar reasoning methods: recall how a similar strategy choice worked, plan a sequence of methods, or generate and evaluate alternative strategies. The distinction is the object of reasoning. Choosing a world action and choosing how to reason about that action can use similar mechanisms while operating on different content.' },
      { id: 'autonomy', title: 'Flexible goals do not require an infinite tower of controllers', sourceSection: 'Discussion Meta-Meta-Reasoning; Example Goal-Based Autonomy; Example Goal-Based Autonomy II', pages: [322, 324], text: 'The lesson rejects the need to posit a separate controller for every meta-level: a metacognitive process can reason about its own strategies recursively. That is an architectural proposal, not proof that monitoring has no computational cost.\n\nGoal-based autonomy asks how an agent can respond to a new goal rather than fail brittly because it was programmed only for an older task. The camera-assembly example motivates reusing and adapting knowledge when asked to disassemble. Robustness comes from knowledge about strategies, their requirements, and the effects of changing them; it does not mean an agent can solve arbitrary tasks without new information.' },
    ],
    sketches: [{ after: 'gaps', title: 'A knowledge gap becomes a learning goal', pages: [317, 317], caption: 'Original schematic of the mug-example gap. Monitoring identifies the missing relationship rather than pretending the explanation is already complete.', alternative: 'An explanation has an unsupported required connection. Meta-reasoning identifies the knowledge gap and creates a learning goal. Retrieve or acquire the missing relationship, then re-evaluate whether the explanation can be completed.', nodes: [['Incomplete explanation', 'A required connection has no supporting knowledge.'], ['Learning goal', 'Acquire the particular missing relationship.'], ['Revised knowledge', 'Check whether the new information supports the explanation.']], edges: [[0, 1, 'identify gap'], [1, 2, 'retrieve or acquire']] }],
    synthesis: 'Meta-reasoning makes an agent’s methods and knowledge objects of inquiry. It connects error repair, learning goals, method selection, and integration into a flexible but still knowledge-dependent architecture.',
  },
  25: {
    summary: 'Advanced topics connect perceptual representation, systems models, design, creativity, and ethics. They are extensions of the course’s methods, not claims that all open problems are solved.',
    sections: [
      { id: 'visual', title: 'Visuospatial content and its encoding are separate choices', sourceSection: 'Visuospatial Reasoning Introduction; Two Views of Reasoning; Symbol Grounding Problem', pages: [328, 330], text: 'Visual knowledge concerns what is present; spatial knowledge concerns where it is and how it is arranged. Causality may be implicit: a spilled cup scene supports a causal inference without explicitly showing the spill process.\n\nAn agent can encode visuospatial content propositionally, using symbolic descriptions, or analogically, preserving structural correspondence with the perceptual situation. In this lesson analogical representation means a modal encoding, not analogical reasoning between source and target problems. The triangle example contrasts manipulating extracted symbolic descriptions with transformations of a structurally corresponding representation.\n\nThe symbol grounding problem concerns how symbols connect to what they stand for in perception and the world. Content being visual does not automatically make its encoding analogical, and naming an object does not explain how that name is grounded. The discussion introduces these issues rather than resolving all of them.' },
      { id: 'models', title: 'Different models expose different information', sourceSection: 'Visuospatial Reasoning An Example; Visuospatial Reasoning Another Example; Ravens Progressive Matrices', pages: [330, 332], text: 'The Galatea example transfers a visuospatial procedure without first extracting the explicit causal pattern used in another account of the same thought experiment. Archytas instead uses known drawings and their models to transfer structure, behavior, and function to a new engineering drawing.\n\nThese are contrasting computational accounts of what is represented and transferred. The lesson also points to visual approaches to matrix problems. These historical systems illustrate research questions; the old project references and claims about the field describe the 2016 context, not current assignment scope or a survey of today’s systems.' },
      { id: 'systems', title: 'Structure, behavior, and function explain a system', sourceSection: 'Systems Thinking Introduction; Systems Thinking Connections; Structure-Behavior-Function', pages: [332, 334], text: 'A system contains interacting components whose processes may span several levels of abstraction. Observed structure alone may not reveal the invisible interactions that produce behavior. Systems thinking seeks an account of those relationships.\n\nA Structure–Behavior–Function model separates components and connections, the causal processes or state transitions, and what the system achieves. The flashlight example identifies battery, switch, and bulb as structure; an enabled flow and energy conversion as behavior; and producing light as function. Models can be nested, with a component analyzed as a system at another level. This supports diagnosis and design because it explains how a structural change can affect an outcome.' },
      { id: 'design', title: 'Open-ended design goes beyond configuring known parts', sourceSection: 'Design Introduction; Agents Doing Design', pages: [335, 337], text: 'Configuration arranges known components; more creative design may change the components or the understanding of the problem. Design thinking addresses ill-defined, underconstrained tasks with problem–solution coevolution.\n\nThe circuit discussion illustrates using a behavior model to propose a change, then learning and transferring a design pattern such as cascading components. Its simplified electrical and pump quantities illustrate pattern transfer, not a general engineering law or safe construction recipe. A candidate design still requires evaluation in its own domain.' },
      { id: 'creativity', title: 'Novelty, value, and unexpectedness are different criteria', sourceSection: 'Creativity Introduction; Defining Creativity II; Exercise Defining Creativity III; Exercise Defining Creativity IV', pages: [337, 340], text: 'The creativity discussion distinguishes a new result, a useful or valuable result, and a non-obvious or surprising result. A larger batch of a familiar recipe may be new in one sense without being surprising. Creative products and the processes producing them are also different objects of study.\n\nAnalogy and explanation-based learning can support creative uses. Emergence reveals a property of a combined structure; re-representation changes how a problem is expressed to make new reasoning possible; serendipity connects an encountered opportunity to an earlier goal. These are examples, not an exhaustive list. Being generated by an explainable algorithm does not by itself disqualify an output as creative: context and the actual result matter.' },
      { id: 'ethics', title: 'Capability does not settle whether a system should be built', sourceSection: 'AI Ethics; Open Issues', pages: [340, 341], text: 'The ethics discussion asks about effects on work and society, military uses and responsibility, and what criteria would matter when considering machines as human-like or as bearers of rights. These are questions for evaluating the consequences and values of AI development, not technical properties automatically established by a successful demonstration.\n\nThe chapter deliberately leaves open issues. A model of reasoning or creativity can clarify what a system does, but does not by itself resolve moral responsibility, distribution of benefits and harms, or justified deployment. Understanding these distinctions is part of the course, not an optional substitute for knowing the mechanisms.' },
    ],
    sketches: [{ after: 'systems', title: 'An SBF explanation connects visible components to function', pages: [334, 334], caption: 'Original schematic of the flashlight model’s explanatory levels. The levels describe different aspects of one system, not three separate devices.', alternative: 'Structure describes the switch, battery, bulb, and their connections. Behavior describes the causal process enabled by the switch and the conversion to light. Function describes the achieved lighting outcome.', nodes: [['Structure', 'Components and connections: switch, battery, bulb.'], ['Behavior', 'Causal processes and state transitions that produce light.'], ['Function', 'The lighting outcome the modeled system achieves.']], edges: [[0, 1, 'enables processes'], [1, 2, 'achieves outcome']] }],
    synthesis: 'The advanced topics extend represent-and-reason to perceptual content, invisible system processes, and novel designs. They also distinguish explaining capability from evaluating its value and ethical consequences.',
  },
  26: {
    summary: 'The wrap-up reconnects the course through seven principles: organized knowledge, incremental learning, expectations, method-task fit, heuristics, recurring patterns, and unified reasoning–memory–learning.',
    sections: [
      { id: 'architecture', title: 'Revisit the situated cognitive system', sourceSection: 'Cognitive Systems Revisited; Course Structure Revisited', pages: [344, 348], text: 'Reaction, deliberation, and metacognition are overlapping spaces in an agent situated in a physical and social world. Reaction maps a percept to an action; deliberation mediates action through knowledge, memory, reasoning, and learning. Metacognition monitors and changes those internal processes.\n\nA failed plan can lead to an alternative plan at the object level or to repairing the planner at the meta level. The course’s topics fit this larger architecture: representations make knowledge available, reasoning methods use it for tasks, learning changes it, and monitoring helps decide when methods or knowledge are inadequate.' },
      { id: 'knowledge', title: 'Organized knowledge and incremental learning', sourceSection: 'The First Principle; The Second Principle', pages: [349, 350], text: 'The first principle is represent, organize, and reason. Semantic networks expose relationships, frames organize expected roles, scripts organize event sequences, and composed explanations connect relevant knowledge fragments. Organization guides and focuses reasoning, not merely storage.\n\nThe second principle is that learning is often incremental. The printed figures revisit recorded cases, discrimination trees, concept revision, version spaces, and corrected explanations. Each new experience can change knowledge or its organization. Incremental does not mean every learning method uses identical updates or that no method needs batch data.' },
      { id: 'methods', title: 'Expectations and method-task fit guide processing', sourceSection: 'The Third Principle; The Fourth Principle', pages: [350, 352], text: 'The third principle combines bottom-up and top-down reasoning. Incoming cues activate knowledge structures, and those structures generate expectations about what to look for or infer. Frames, scripts, and constraints exemplify this interaction.\n\nThe fourth principle matches methods to tasks. A broad method such as generate and test is not automatically the best for every task; specialized knowledge may make another method more useful. Methods also create subtasks that can use different methods, so matching recurs throughout the task hierarchy. Meta-reasoning makes that selection and integration explicit.' },
      { id: 'limits', title: 'Heuristics and recurrence address resource limits', sourceSection: 'The Fifth Principle; The Sixth Principle', pages: [353, 355], text: 'The fifth principle uses heuristics for good-enough solutions under bounded resources. Satisficing seeks an adequate solution rather than exhaustive optimization when the latter is too expensive. The earlier limitations of means-ends analysis show why a heuristic’s usefulness is not a universal success guarantee.\n\nThe sixth principle exploits recurring patterns. Cases, analogies, and configuration plans reuse useful structure instead of solving every detail anew. Recurrence does not contradict novelty: an agent can transfer or adapt a known pattern to a new situation. The fit must still be evaluated.' },
      { id: 'unity', title: 'Reasoning, learning, and memory support and constrain one another', sourceSection: 'The Seventh Principle; Current Research', pages: [356, 357], text: 'The seventh principle unifies the three processes. Memory stores and organizes knowledge; learning acquires or changes it; reasoning uses it. The production-system impasse is the clearest example: reasoning cannot decide, memory supplies an episode, chunking learns a rule, and reasoning proceeds.\n\nThe corrected-cup and explanation examples show the same interdependence through different mechanisms. The listed research systems are historical pointers to further study, not a complete current inventory. The course closes with a framework for relating methods and identifying their knowledge requirements, not one algorithm that resolves every problem in intelligence.' },
    ],
    sketches: [{ after: 'unity', title: 'The course returns to one connected explanation', pages: [356, 356], caption: 'Original wrap-up schematic. The connections capture the seventh principle; different lessons realize them with different knowledge structures and methods.', alternative: 'Memory supplies organized knowledge to reasoning. Reasoning exposes learning needs and produces results. Learning updates what memory retains, enabling later reasoning. The agent’s actions and feedback connect this internal cycle to the world.', nodes: [['Memory', 'Retain and retrieve organized knowledge.'], ['Reasoning', 'Use knowledge for interpretation and action; expose gaps.'], ['Learning', 'Acquire and revise knowledge from experience and reasoning needs.']], edges: [[0, 1, 'available knowledge'], [1, 2, 'needs and feedback'], [2, 0, 'updated knowledge']] }],
    synthesis: 'The seven principles are a connected account of knowledgeable, resource-bounded intelligence. A useful explanation states the task, representation, method, memory and learning contributions, and the conditions under which the result is supported.',
  },
  5: {
    summary: 'Means-ends analysis chooses moves by their difference from a goal. Problem reduction breaks a goal into smaller problems; the blocks world shows why neither method alone resolves interacting goals.',
    sections: [
      { id: 'state-space', title: 'State spaces: what is being searched?', pages: [54, 55], text: 'A state describes the current arrangement of the problem. An operator changes that arrangement. The state space contains the states reachable by applying operators repeatedly; solving the problem means finding a path from the initial state to a goal state. States are the nodes, and legal applications of operators are the directed edges. A path is therefore a sequence of actions, not just a list of pictures that resemble the goal.\n\nThe book uses a blocks world: initially A and B are on the table and C is on A; the goal is C on the table, B on C, and A on B. Only one block may move at a time, and a block with another block on it cannot move. These constraints determine which edges exist. Moving C to the table, then B onto C, then A onto B is a legal path. The next question is not whether that path exists, but how an agent selects it among other legal moves.' },
      { id: 'means-ends', title: 'Means-ends analysis: use differences to select a move', pages: [55, 56], text: 'Means-ends analysis compares the current state with the goal, identifies differences, and chooses an applicable operator that brings the state closer to the goal. Reducing a difference is the end; applying an operator is the means. Here “distance” is an abstract measure of discrepancy, not physical distance on the table.\n\nFor the three-block example, count blocks whose support differs from the desired support. Initially there are three differences. Moving C to the table reduces the count to two; moving B onto C reduces it to one; moving A onto B reduces it to zero. This heuristic makes one successful path look attractive. But moving B onto C in the initial state also reduces the count to two. The heuristic alone does not resolve that tie. Do not infer a complete planning algorithm from this local selection rule: the lesson deliberately leaves some choices unresolved.' },
      { id: 'interactions', title: 'Why getting closer can trap the search', pages: [57, 59], text: 'The four-block example starts with B on C, D on B, and A on the table. The goal is the tower A on B on C on D, with D on the table. Moving D to the table achieves one missing relation; moving A onto B achieves another. Only C on D remains wrong, so the difference count is now one.\n\nYet C cannot move: B is on it, and A is on B. Achieving the remaining relation requires taking A off B and B off C, temporarily breaking relations that already match the final goal. A rule that insists on immediate discrepancy reduction cannot justify those preparatory moves. The book uses this obstacle to show that means-ends analysis may fail to make progress or enter loops. Its general applicability is not a guarantee of convergence, computational efficiency, or an optimal solution.' },
      { id: 'problem-reduction', title: 'Problem reduction: solve subproblems, then recompose', pages: [60, 62], text: 'Problem reduction is a different idea: decompose a hard problem into smaller, easier problems, solve them, and combine the subsolutions. Knowledge helps identify a useful decomposition. For the tower, the final goal can be described as four subgoals: D on the table, C on D, B on C, and A on B.\n\nThe lesson focuses first on C on D while retaining D on the table. Relative to this smaller goal, the earlier matches A on B and B on C are no longer achievements that must be preserved at every step. Move A to the table, move B to the table to clear C, and then move C onto D. Finally put B on C and A on B to recompose the complete tower.\n\nThis explanation is not a claim that problem reduction automatically discovers that ordering. The book explicitly asks why C on D should be selected first and why placing A on D is a worse tied choice than placing A on the table. Subgoals can obstruct one another; decomposition alone does not solve their ordering or interaction. Planning returns to these unanswered questions later.' },
      { id: 'weak-methods', title: 'Why these are called weak methods', pages: [63, 66], text: 'The visual-analogy discussion combines the methods: find a transformation between two known panels, transfer it to a new panel, and compare the generated candidates with the choices. That is a decomposition; individual transformations can reduce differences; candidate comparison uses generate and test. A semantic network can support all three, so a complex problem need not use only one reasoning method.\n\n“Weak” does not mean useless. These methods make relatively little use of domain knowledge, and their coupling to a particular knowledge representation is weak. That makes them broadly applicable, including in unfamiliar domains. Knowledge-intensive methods can exploit stronger domain structure to guide inference, but require that knowledge to be available. The historical Raven example illustrates this relationship; it is not the current ARC-AGI assignment specification.' },
    ],
    sketches: [
      { after: 'means-ends', title: 'A legal path through the three-block state space', pages: [54, 56], caption: 'Original schematic of the book’s three-block path. Each arrow is a legal move; d counts support relations that differ from the goal.', alternative: 'Start: C on A, A and B on the table, d=3. Move C to the table: all three blocks on the table, d=2. Move B onto C: B on C and A on the table, d=1. Move A onto B: A on B on C, d=0.', nodes: [['C on A; B on table', 'A is also on the table. Three support relations differ from the goal.'], ['All on table', 'C has been cleared from A. Two support relations differ.'], ['B on C; A on table', 'C remains on the table. Only A’s support differs.'], ['A on B on C', 'C is on the table. All goal support relations hold.']], edges: [[0, 1, 'C to table'], [1, 2, 'B onto C'], [2, 3, 'A onto B']] },
      { after: 'problem-reduction', title: 'Clearing a subgoal before rebuilding the tower', pages: [60, 62], caption: 'Original schematic of the problem-reduction example. Breaking an achieved final-goal relation can be necessary to achieve the selected subgoal.', alternative: 'With A on B on C and D on the table, C is blocked. Move A to the table, then B to the table. C is now clear and can move onto D. Rebuild B on C, then A on B. Problem reduction selects a smaller goal; it does not itself guarantee this ordering.', nodes: [['A on B on C', 'D is on the table. C cannot move while A and B remain above it.'], ['Clear C', 'Move A to the table, then move B to the table.'], ['C on D', 'The chosen subgoal holds; D stays on the table.'], ['A on B on C on D', 'Recompose by moving B onto C and A onto B.']], edges: [[0, 1, 'remove blockers'], [1, 2, 'C onto D'], [2, 3, 'rebuild above C']] },
    ],
    synthesis: 'A state space says which moves are possible. Means-ends analysis supplies a heuristic for choosing among them; problem reduction changes the problem into subproblems. The blocks world exposes the gap between reducing a local difference and coordinating an entire solution.',
  },
  6: {
    summary: 'Production systems explain action selection through rules and changing working memory. In the book’s pitcher example, an unresolved choice creates an impasse, and chunking learns a production from episodic knowledge.',
    sections: [
      { id: 'architecture', title: 'From perceptual history to action', pages: [68, 71], text: 'A cognitive agent can be described as mapping its perceptual history to an action. A cognitive architecture explains the mechanisms that make that mapping possible. The baseball pitcher is the running example: observations about the game and the goal of escaping the inning must lead to an action such as walking a batter or throwing a particular pitch.\n\nThe book distinguishes three levels of explanation. The task/knowledge level says what decision is required and what knowledge is available. The algorithm/symbol level says how that knowledge is represented and manipulated. The hardware level says how those processes are implemented. These are complementary descriptions: knowing the task does not specify the algorithm, and naming the hardware does not explain the knowledge used.\n\nThe architecture discussion assumes goal-directed agents in rich, changing environments. They use symbolic abstractions of world knowledge, adapt behavior to circumstances, and learn from experience. “Architecture + content = behavior” captures the central design idea: holding the architecture fixed while changing its knowledge content can produce different behavior. It does not make the content or its adequacy irrelevant.' },
      { id: 'memory', title: 'Working memory and three kinds of long-term knowledge', pages: [72, 74], text: 'The lesson introduces SOAR as a cognitive architecture and concentrates on its deliberative role. Working memory holds the current represented situation and goals: the inning, occupied bases, batter, and goal in the pitcher example. These are feature-value descriptions, not the world itself.\n\nLong-term memory includes procedural knowledge (how to do something), semantic knowledge (general concepts and models), and episodic knowledge (particular past events). Production rules represent procedural knowledge as conditions and consequences: if the antecedent matches, establish its consequent. Goals and observations can both occur in the conditions. Working memory supplies the current content against which rules are matched; episodic memory will later supply experience for learning. These roles are not interchangeable.' },
      { id: 'rule-cycle', title: 'Rules change working memory, enabling further rules', pages: [74, 77], text: 'In the first pitcher situation, there are two outs, runners on second and third, and no runner on first. A matching rule suggests the goal of intentionally walking the batter. A further rule suggests the intentional-walk operator. The execution rule can then send the single selected operator to the motor system and record the action in working memory. Rule application can establish an intermediate goal, not merely trigger an immediate physical action.\n\nAfter the walk, first base is occupied too. The production rules have not changed, but working memory has. A different rule now establishes the goal of getting the next batter out by pitching. With the right-handed batter in the example, the rules suggest a curve ball and the single-operator execution condition is satisfied.\n\nThis is a continuing interaction: matching rules establish consequences, consequences change working memory, and the new contents enable other rules. Working memory changes rapidly as the situation and intermediate conclusions change; long-term knowledge is more persistent. The changed decision after the walk is reasoning with new state information, not yet learning a new rule.' },
      { id: 'impasse', title: 'An impasse is a missing decision, not a chosen action', pages: [77, 78], text: 'Now the opposing team substitutes a left-handed batter. The same procedural knowledge suggests both a curve-ball operator and a fast-ball operator. The rule that executes an action requires exactly one selected operator, so it cannot fire. The system has reached an impasse: it cannot decide between competing actions. The book also allows an impasse when insufficient knowledge prevents a decision.\n\nThe important distinction is between having applicable rules and having enough knowledge to settle the action. This example does not say to execute both pitches or arbitrarily take the first rule. The architectural response is to seek knowledge that can resolve the impasse.' },
      { id: 'chunking', title: 'Chunking: use an episode to learn a production', pages: [78, 79], text: 'Episodic memory contains a previous encounter with the same batter, Parra: a fast ball resulted in a home run. Given the current goal of avoiding that outcome, the lesson’s learning process encapsulates relevant knowledge from the episode in a production: when two operators are suggested, one is a fast ball, and the batter is Parra, dismiss the fast-ball operator. This is the example of chunking.\n\nThe learned rule becomes procedural knowledge. Applying it in the current situation leaves the curve-ball operator as the sole suggestion, so the existing execution rule can fire. The architecture is unchanged; its content has changed. This is the learning step, distinct from the earlier working-memory changes.\n\nThe reasoning failure determines why and when to learn (resolve the impasse), what to learn (a deciding rule), and where to look (relevant episodic evidence); only then does the account specify how to learn it. Thus reasoning, memory, and learning form one connected explanation. This is the book’s illustrative model of decision making, not statistical proof that a fast ball always fails against that batter. Its cognitive connection discusses production systems as models of human behavior in restricted tasks, not a complete model of all human cognition.' },
    ],
    sketches: [
      { after: 'rule-cycle', title: 'The production-system interaction', pages: [74, 77], caption: 'Original schematic: procedural knowledge is matched against working memory; consequences update the state that later matches use. A motor action requires an applicable execution condition.', alternative: 'Working memory holds percepts and goals. Match its contents against production antecedents. Establish the matching consequences in working memory, enabling further matches. Execute an action only when its execution condition is met.', nodes: [['Working memory', 'Current percepts, goals, and intermediate conclusions.'], ['Match productions', 'Compare current facts with antecedents in procedural memory.'], ['Establish consequences', 'Add a goal, suggest an operator, or record a result.']], edges: [[0, 1, 'current facts'], [1, 2, 'matching rule'], [2, 0, 'update memory']] },
      { after: 'chunking', title: 'From an unresolved pitch choice to a learned rule', pages: [77, 79], caption: 'Original schematic of the pitcher’s impasse. The episode supplies knowledge for a new production; the production resolves the current choice.', alternative: 'Both curve ball and fast ball are suggested. An earlier Parra episode records a home run after a fast ball. Chunking learns the rule to dismiss the fast ball under the stated competing-operator conditions. Curve ball remains the single operator.', nodes: [['Curve ball or fast ball?', 'Two suggested operators prevent the single-operator rule from firing.'], ['Parra episode', 'A previous fast ball to this batter resulted in a home run.'], ['Learn dismiss-fast-ball rule', 'Conditions include two suggestions, fast ball among them, and batter Parra.'], ['Curve ball remains', 'The single-operator execution condition can now be met.']], edges: [[0, 1, 'seek experience'], [1, 2, 'chunk relevant result'], [2, 3, 'apply learned rule']] },
    ],
    synthesis: 'The pitcher progression separates three changes: new percepts change working memory; an impasse exposes inadequate procedural knowledge; chunking changes that knowledge using an episode. Action selection and learning are explained together rather than treated as unrelated tasks.',
  },
};

const source = (pages: [number, number], section: string): Citation => ({
  sourceId: 'ebook-2016', pdfPage: pages[0], ...(pages[1] !== pages[0] ? { pdfPageEnd: pages[1] } : {}),
  section, verification: 'verified',
});

