export function lessonBlocks(chapter: CoursePack['chapters'][number], lesson: LessonNotes, concepts: CoursePack['concepts']): Block[] {
  const result: Block[] = [];
  for (const section of lesson.sections) {
    const locator = section.sourceSection ?? sourceSections[chapter.number]?.[section.id];
    if (!locator) throw new Error(`Missing source heading: lesson ${chapter.number}, ${section.id}`);
    const conceptIds = concepts.filter(concept => [concept.term, ...concept.aliases].some(term => section.text.toLowerCase().includes(term.toLowerCase()))).map(concept => concept.id);
    if (chapter.number === 12 && section.id === 'truth') conceptIds.push('kbai-predicate');
    result.push({ id: `${chapter.id}-notes-${section.id}`, kind: 'callout', tone: 'note', title: section.title, text: section.text, conceptIds, citations: [source(section.pages, locator)] });
    lesson.tables?.filter(table => table.after === section.id).forEach((table, index) => {
      result.push({ id: `${chapter.id}-notes-${section.id}-table-${index + 1}`, kind: 'table', title: table.title, columns: table.columns, rows: table.rows, conceptIds, citations: [source(table.pages, table.sourceSection)] });
    });
    lesson.sketches.filter(sketch => sketch.after === section.id).forEach((sketch, index) => {
      const nodes = sketch.nodes.map(([label, detail], i) => ({ id: `n${i}`, label, detail, column: 0 }));
      result.push({
        id: `${chapter.id}-notes-${section.id}-diagram-${index + 1}`, kind: 'diagram', title: sketch.title,
        caption: sketch.caption, alternative: sketch.alternative, nodes,
        edges: sketch.edges.map(([from, to, label]) => ({ from: `n${from}`, to: `n${to}`, label })),
        steps: [{ title: 'Concept map', explanation: sketch.alternative, activeNodeIds: nodes.map(node => node.id) }],
        conceptIds, citations: [source(sketch.pages, locator), { sourceId: 'original-handbook', section: 'Original explanatory schematic', verification: 'verified' }],
      });
    });
  }
  result.push({ id: `${chapter.id}-notes-synthesis`, kind: 'callout', tone: 'note', title: 'What this lesson adds', text: lesson.synthesis, conceptIds: [], citations: [] });
  result.push(...chapter.blocks.filter(block => block.kind === 'recall'));
  return result;
}

export const week3 = {
  title: 'Goal-directed problem solving and rule-based action',
  overview: 'This week asks how an agent decides what to do next. Means-ends analysis uses the difference between a current state and a goal to guide search; problem reduction tackles a complex goal through smaller problems. Production systems then give a concrete architecture in which current facts and goals activate rules. The connection is action selection: the blocks world exposes unresolved choices, and the pitcher example shows how an architecture can use memory and learning when its rules cannot decide.',
  synthesis: 'Across these lessons, a goal is not enough to determine an action. The agent also needs a representation, available operators or rules, and knowledge for choosing between alternatives. The limits of a difference heuristic motivate subproblems and, later, planning; the limits of an existing rule set motivate an impasse and chunking. Keep the two levels separate: searching a world-state space is not the same as changing the knowledge used to search or act.',
};

export const weeklyNotes: Record<number, { overview: string; synthesis: string }> = {
  1: { overview: 'Knowledge-based AI asks how limited agents use knowledge to understand situations and choose actions. The introduction connects reasoning, learning, and memory; the course overview then uses visual analogy to expose different ways an agent might solve the same problem. Read these together as the course’s organizing framework, not a list of unrelated AI techniques.', synthesis: 'The starting point is a task, represented knowledge, and a reasoning process. Human-like cognition and rational task performance are distinct aims. The seven course principles connect what follows: organize knowledge, learn incrementally, use expectations, match methods to tasks, work within resource limits, exploit recurring patterns, and connect reasoning with memory and learning.' },
  2: { overview: 'Semantic networks describe the objects, relationships, and states an agent reasons about. Generate and test explains how it uses that description to propose and reject possibilities. Together they introduce represent-and-reason: a useful notation makes the task computable, but a method must still decide what to do with it.', synthesis: 'A network can describe spatial relations, transformations, or a state space. A generator proposes candidates and a tester evaluates them. The source’s recurring-state and ambiguity examples show why legal states, productive search, and preferred matches are different judgments.' },
  3: week3,
  4: { overview: 'Frames organize expectations about a situation into slots and fillers. Recording cases organizes past experiences so a similar problem can retrieve a candidate answer. Both lessons show how memory supplies useful structure, but neither defaults nor a nearest case should be confused with a guaranteed fact or unchanged solution.', synthesis: 'Frames supply a structured expectation to be filled and corrected; cases supply a remembered experience selected through a similarity representation. Defaults remain defeasible, and distance measures remain task-dependent. A retrieved route can still need adaptation even if it is the nearest one.' },
  5: { overview: 'Case-based reasoning turns remembered experience into a complete problem-solving process. The key addition to last week’s retrieval is reasoning about differences: adapt an old solution, evaluate the candidate, and decide what useful experience to store. The route examples keep these roles separate and show where failure sends the process back.', synthesis: 'Reuse is not copying. Adaptation uses a world model, other cases, or rules; evaluation checks the current requirements. Indices and discrimination trees make cases retrievable, while selective storage avoids treating every added case as an improvement.' },
  6: { overview: 'Incremental concept learning explains how a concept changes as labeled examples arrive. Classification explains how organized concepts are then used to interpret percepts and guide action. The connection is abstraction: a learner moves beyond individual cases, but the kind of concept determines what a definition and a classification method can legitimately do.', synthesis: 'Generalization repairs a missed positive; specialization repairs a covered negative. Background knowledge and heuristics guide that revision. Classification then uses formal conditions, defeasible prototypes, or exemplars as appropriate, with top-down refinement or bottom-up abstraction fitted to the task.' },
  7: { overview: 'Logic makes the knowledge and inference steps of an agent explicit. Start with statements and connectives, use truth tables to justify equivalent rewrites, then follow the robot’s resolution proof. This week also includes Exam 1 review of Lessons 01–12.', synthesis: 'A knowledge base states premises; an inference engine derives what follows. Quantifiers express scope, while the worked resolution examples return to propositional clauses and refute a negated conclusion. For the earlier lessons, keep representations, reasoning methods, architectures, and learning processes distinct: a network is not a generator, a frame default is not a theorem, and retrieval is not adaptation.' },
  8: { overview: 'Planning and understanding both use structured knowledge to resolve choices. Planning coordinates actions whose effects and preconditions can interfere; understanding coordinates grammatical cues and thematic roles to select an interpretation. Both build on earlier representations while making the source of each constraint explicit.', synthesis: 'Planning resolves the goal interactions left open in means-ends analysis and problem reduction. Understanding resolves meaning through role constraints and background knowledge. A compatible plan must support its required conditions; a compatible interpretation must fit the actual sentence and context.' },
  9: { overview: 'Commonsense reasoning abstracts surface wording into primitive actions and resultant states. Scripts connect those event frames into familiar sequences, such as a restaurant visit. Together the lessons move from understanding one action to understanding a longer story and predicting what should happen next.', synthesis: 'Different words can share an underlying action without having identical connotations. Primitive frames capture roles and effects; scripts add entry conditions, results, props, roles, tracks, and scenes. Expected events can fail to happen, and unexpected events can happen: both require comparing stored expectations with the actual situation.' },
  10: { overview: 'Explanation-based learning and analogical reasoning use prior knowledge to address something new. The first composes causal fragments to explain why an object fits a required concept. The second retrieves a source, maps corresponding relations, and transfers useful knowledge across domains. Both need a justified connection, not merely a resemblance.', synthesis: 'Abstraction selects what matters from a source; transfer applies it where the target’s conditions support it. The mug’s missing link stays a gap, and a cross-domain analogy remains a proposal until evaluated. Compound and compositional analogies show that transfer can involve several sources or several levels rather than one copied answer.' },
  11: { overview: 'Version spaces constrain alternative concept hypotheses using labeled examples. Constraint propagation constrains alternative interpretations using shared variables and structural rules. The common idea is to make possibilities explicit and eliminate incompatible ones, while keeping the two kinds of evidence distinct.', synthesis: 'Examples restrict what a learned concept can cover; junction and grammatical constraints restrict which assignments can coexist. Version-space convergence needs informative consistent evidence and an adequate hypothesis form. Propagation can leave multiple interpretations or reveal conflicts under an inadequate ontology. Neither method should be presented as a guarantee of one true answer in every problem.' },
  12: { overview: 'Configuration and diagnosis are tasks that can use several reasoning methods. Configuration seeks an arrangement of known components satisfying requirements; diagnosis seeks fault explanations for a discrepancy in behavior. The chair and malfunction examples connect representations, global constraints, evaluation, and feedback.', synthesis: 'Configuration refines a candidate arrangement and checks the whole specification. Diagnosis compares explanatory coverage, parsimony, and confidence and can request further observations. Designing a change and explaining a failure are different tasks, even when both use cases, rules, constraints, or models.' },
  13: { overview: 'Learning by correcting mistakes uses feedback to identify and repair an agent’s own mistaken knowledge. Meta-reasoning broadens that idea to errors, gaps, method selection, and strategy integration. The connection is self-directed inquiry: a failed result identifies a problem to investigate, not a magic instruction that repairs the agent automatically.', synthesis: 'A suspicious feature is not yet a causal explanation. The corrected-cup example shows why repair must preserve valid distinctions such as liftable versus suitable for drinking. Meta-reasoning then turns missing knowledge into learning goals and chooses methods according to their requirements, costs, and supported solution quality.' },
  14: { overview: 'Advanced Topics connects visuospatial representation, systems thinking, design, creativity, and ethics. These are not five replacement algorithms: they extend the course’s questions about what is represented, how an explanation is built, how novel solutions are evaluated, and what consequences of capability deserve scrutiny.', synthesis: 'Keep content separate from encoding, analogical representation separate from analogical reasoning, and structure separate from behavior and function. Design can change the problem as well as the solution; creativity involves distinct judgments of novelty, value, and unexpectedness. Technical success does not resolve ethical questions about using an agent.' },
  15: { overview: 'There are no new lessons this week. Consolidate the course’s representations, reasoning methods, and evaluation ideas alongside the final ARC-AGI project. The earlier weekly notes remain available by topic.', synthesis: 'Connect the representation an agent uses with the reasoning it affords, the experiences it can retrieve, and the evidence used to evaluate a result. Configuration, diagnosis, analogy, and meta-reasoning offer different perspectives on that connection.' },
  16: { overview: 'There are no new lessons this week. Review Lessons 13–25 for Exam 2, including earlier concepts where they support those later mechanisms. Focus on how each method uses knowledge and what its conclusions do and do not establish.', synthesis: 'Planning coordinates conditions and effects; understanding and scripts coordinate meaning and expectations; explanation and analogy justify transfer; version spaces and constraints retain compatible possibilities; configuration and diagnosis address different tasks; corrective learning and meta-reasoning revise the agent’s own knowledge and methods.' },
  17: { overview: 'Wrap-Up reconnects the whole course through the cognitive-system architecture and seven recurring principles. This week adds synthesis, not another isolated method: organized knowledge, incremental learning, top-down expectations, method-task fit, heuristics, recurring patterns, and the unity of reasoning, memory, and learning explain how the earlier topics fit together.', synthesis: 'The useful final picture is an agent situated in a changing world, selecting actions through representations and methods it can learn, retrieve, and monitor. Understanding KBAI means being able to explain those relationships and their limits, rather than recognizing twenty-six disconnected lesson titles.' },
};
